// =====================================================================
// I Macabeus — tradução do grego, cotejado com a Nova Vulgata (versificação: Nova Vulgata)
// Formato: {s:"subtítulo"} abre trecho; {v,t,n} prosa; {v,l:[...]} verso;
// np:1 marca início de parágrafo.
// =====================================================================

window.TEXTOS_SEED["1macabeus"][1] = [
{s:"Alexandre Magno e os seus sucessores"},
{v:1,t:"Depois que Alexandre, filho de Filipe, o macedônio, que antes reinara sobre a Grécia, saiu da terra de Cetim, derrotou Dario, rei dos persas e dos medos, e reinou em seu lugar,",n:"O primeiro livro dos Macabeus narra a resistência dos judeus contra os reis selêucidas da Síria, de 175 a 134 a.C., desde Antíoco IV Epífanes até a morte de Simão. Foi escrito em hebraico, por volta de 100 a.C., mas só chegou até nós em grego. Cetim é propriamente Chipre; aqui designa a Grécia e a Macedônia."},
{v:2,t:"travou muitas guerras, apoderou-se de fortalezas e matou reis da terra;"},
{v:3,t:"avançou até os confins da terra e tomou despojos de uma multidão de nações. A terra calou-se diante dele; e ele se exaltou, e o seu coração se ensoberbeceu."},
{v:4,t:"Reuniu um exército muito poderoso e dominou países, nações e soberanos, que lhe pagaram tributo."},
{v:5,t:"Depois disso caiu de cama e percebeu que ia morrer."},
{v:6,t:"Chamou os seus oficiais mais ilustres, que tinham sido criados com ele desde a juventude, e repartiu entre eles o seu reino, enquanto ainda vivia.",n:"Na realidade, Alexandre não repartiu o império; os seus generais o dividiram entre si depois da morte dele, em 323 a.C."},
{v:7,t:"Alexandre reinou doze anos e morreu."},
{v:8,t:"Os seus oficiais assumiram o poder, cada um na sua região."},
{v:9,t:"Depois da morte dele, todos cingiram o diadema, e depois deles os seus filhos, durante muitos anos; e multiplicaram os males sobre a terra."},
{s:"Antíoco Epífanes e os judeus helenizantes"},
{v:10,t:"Deles saiu um rebento pecador, Antíoco Epífanes, filho do rei Antíoco, que tinha estado em Roma como refém; e começou a reinar no ano cento e trinta e sete do reino dos gregos.",n:"O livro conta os anos pela era dos selêucidas, que começa em 312 a.C.; o ano cento e trinta e sete corresponde a 175 a.C."},
{v:11,t:"Naqueles dias surgiram de Israel homens sem lei, que seduziram muitos, dizendo: Vamos fazer aliança com as nações que nos rodeiam, porque, desde que nos separamos delas, caíram sobre nós muitos males."},
{v:12,t:"A proposta pareceu-lhes boa,"},
{v:13,t:"e alguns do povo se apressaram a ir ter com o rei, que lhes deu autorização para seguirem os costumes das nações."},
{v:14,t:"Construíram em Jerusalém um ginásio, segundo os costumes das nações;",np:1},
{v:15,t:"disfarçaram a circuncisão, abandonaram a aliança santa, associaram-se às nações e venderam-se para fazer o mal.",n:"Literalmente: refizeram os prepúcios. Com uma operação, apagavam o sinal da circuncisão, para não serem ridicularizados nos exercícios do ginásio, que se praticavam nus."},
{s:"Antíoco saqueia o templo"},
{v:16,t:"Quando se sentiu firme no reino, Antíoco decidiu apoderar-se também da terra do Egito, para reinar sobre os dois reinos."},
{v:17,t:"Entrou no Egito com um exército imponente, com carros, elefantes, cavaleiros e uma grande frota;"},
{v:18,t:"travou guerra contra Ptolomeu, rei do Egito; Ptolomeu recuou diante dele e fugiu, e muitos caíram feridos.",np:1},
{v:19,t:"Tomaram as cidades fortificadas do Egito, e Antíoco levou os despojos da terra do Egito."},
{v:20,t:"Depois de ter vencido o Egito, no ano cento e quarenta e três, Antíoco voltou e subiu contra Israel; subiu a Jerusalém com um exército imponente.",n:"Ano cento e quarenta e três: 169 a.C."},
{v:21,t:"Entrou com arrogância no santuário e levou o altar de ouro, o candelabro da luz com todos os seus utensílios,"},
{v:22,t:"a mesa dos pães da oferenda, os vasos das libações, as taças, os incensórios de ouro, o véu, as coroas e os ornamentos de ouro da fachada do templo; e arrancou todo o ouro."},
{v:23,t:"Tomou a prata, o ouro e os objetos preciosos, e tomou os tesouros escondidos que encontrou;",np:1},
{v:24,t:"e, levando tudo, voltou para a sua terra. Fez uma matança e proferiu palavras de grande arrogância."},
{v:25,t:"Houve grande luto em Israel, em todo lugar onde habitavam.",np:1},
{v:26,t:"Gemeram os chefes e os anciãos, as virgens e os jovens perderam as forças, e a beleza das mulheres se desfez."},
{v:27,t:"Todo noivo entoou um lamento, e a noiva sentada no quarto nupcial chorava."},
{v:28,t:"A terra estremeceu por causa dos seus habitantes, e toda a casa de Jacó se vestiu de vergonha."},
{s:"A destruição de Jerusalém e a Cidadela"},
{v:29,t:"Dois anos depois, o rei enviou às cidades de Judá um cobrador de tributos, que chegou a Jerusalém com um exército imponente.",n:"Cobrador de tributos: talvez uma leitura errada do hebraico; 2 Macabeus 5,24 diz que era Apolônio, chefe dos mísios, e em hebraico as duas expressões se parecem."},
{v:30,t:"Falou-lhes com palavras de paz, mas com astúcia, e eles acreditaram nele. Então atacou a cidade de surpresa, feriu-a com um golpe terrível e matou muita gente de Israel."},
{v:31,t:"Saqueou a cidade, incendiou-a e derrubou as suas casas e as muralhas ao redor."},
{v:32,t:"Levaram cativas as mulheres e as crianças e apoderaram-se do gado."},
{v:33,t:"Depois fortificaram a Cidade de Davi com uma muralha grande e forte, com torres fortes, e ela se tornou a sua cidadela.",np:1,n:"Cidadela: em grego, Acra, a fortaleza selêucida dentro de Jerusalém, junto ao templo, que só será tomada por Simão em 141 a.C. (13,49–51)."},
{v:34,t:"Puseram ali uma gente pecadora, homens sem lei, que se fortificaram nela."},
{v:35,t:"Armazenaram armas e víveres, reuniram os despojos de Jerusalém e os depositaram ali; e a cidadela tornou-se uma grande armadilha."},
{v:36,t:"Foi uma cilada para o santuário e um adversário perverso para Israel, continuamente."},
{v:37,t:"Derramaram sangue inocente ao redor do santuário e profanaram o santuário."},
{v:38,t:"Por causa deles, os habitantes de Jerusalém fugiram; ela tornou-se morada de estrangeiros, tornou-se estranha à sua própria descendência, e os seus filhos a abandonaram."},
{v:39,t:"O seu santuário ficou deserto como um ermo, as suas festas se transformaram em luto, os seus sábados em opróbrio, a sua honra em desprezo."},
{v:40,t:"Tão grande quanto a sua glória foi a sua desonra, e a sua grandeza se transformou em luto."},
{s:"A perseguição religiosa"},
{v:41,t:"O rei escreveu a todo o seu reino que todos formassem um só povo"},
{v:42,t:"e que cada um abandonasse os seus costumes. Todas as nações aceitaram a ordem do rei."},
{v:43,t:"Também muitos de Israel se agradaram do seu culto: ofereceram sacrifícios aos ídolos e profanaram o sábado."},
{v:44,t:"O rei enviou, por meio de mensageiros, cartas a Jerusalém e às cidades de Judá, ordenando que seguissem costumes estranhos à terra,"},
{v:45,t:"que suprimissem do santuário os holocaustos, o sacrifício e a libação, que profanassem os sábados e as festas,"},
{v:46,t:"que contaminassem o lugar santo e os santos,"},
{v:47,t:"que construíssem altares, recintos sagrados e templos de ídolos, que sacrificassem porcos e animais impuros,"},
{v:48,t:"que deixassem os seus filhos incircuncisos e se tornassem abomináveis com toda espécie de impureza e profanação,"},
{v:49,t:"de modo que esquecessem a Lei e mudassem todos os preceitos."},
{v:50,t:"Quem não agisse conforme a ordem do rei seria morto."},
{v:51,t:"Foi nesses termos que escreveu a todo o seu reino; nomeou inspetores sobre todo o povo e ordenou às cidades de Judá que oferecessem sacrifícios, cidade por cidade."},
{v:52,t:"Muitos do povo se juntaram a eles, todos os que abandonavam a Lei, e fizeram o mal na terra;"},
{v:53,t:"e obrigaram Israel a esconder-se em todos os seus refúgios."},
{v:54,t:"No dia quinze do mês de Casleu, no ano cento e quarenta e cinco, o rei erigiu sobre o altar a abominação da desolação; e nas cidades de Judá, ao redor, construíram altares;",np:1,n:"Ano cento e quarenta e cinco: dezembro de 167 a.C. A abominação da desolação era um altar pagão, dedicado a Zeus Olímpico (2 Macabeus 6,2), levantado sobre o altar dos holocaustos. A expressão vem de Daniel 9,27; 11,31; 12,11, e Jesus a retoma (Mateus 24,15)."},
{v:55,t:"e queimavam incenso às portas das casas e nas praças."},
{v:56,t:"Rasgavam e queimavam os livros da Lei que encontravam."},
{v:57,t:"Se encontravam com alguém um livro da aliança, ou se alguém se mostrava fiel à Lei, o decreto do rei o condenava à morte."},
{v:58,t:"Assim, com a força que tinham, agiam mês após mês contra os israelitas que encontravam nas cidades."},
{v:59,t:"No dia vinte e cinco de cada mês, ofereciam sacrifícios no altar pagão levantado sobre o altar dos holocaustos.",n:"O dia vinte e cinco era, provavelmente, a data em que se celebrava todo mês o aniversário do rei."},
{v:60,t:"As mulheres que tinham feito circuncidar os seus filhos eram mortas, conforme o decreto"},
{v:61,t:"— e penduravam as criancinhas ao pescoço delas —, e também as suas famílias e os que os tinham circuncidado."},
{v:62,t:"Mas muitos em Israel se mantiveram firmes e resolveram no seu íntimo não comer nada de impuro;"},
{v:63,t:"preferiram morrer a contaminar-se com aqueles alimentos e profanar a aliança santa; e morreram."},
{v:64,t:"Uma ira muito grande caiu sobre Israel."}
];

window.TEXTOS_SEED["1macabeus"][2] = [
{s:"Matatias e os seus filhos"},
{v:1,t:"Naqueles dias, Matatias, filho de João, filho de Simeão, sacerdote da descendência de Joiarib, partiu de Jerusalém e foi morar em Modin."},
{v:2,t:"Tinha cinco filhos: João, chamado Gadis;"},
{v:3,t:"Simão, chamado Tasi;"},
{v:4,t:"Judas, chamado Macabeu;",n:"Macabeu: apelido de sentido incerto, talvez martelo (em hebraico, maqqebet). Passou depois a designar toda a família e os que combateram com ela."},
{v:5,t:"Eleazar, chamado Abaran; e Jônatas, chamado Afus."},
{v:6,t:"Vendo as blasfêmias que se cometiam em Judá e em Jerusalém,",np:1},
{v:7,t:"Matatias disse: Ai de mim! Por que nasci para ver a ruína do meu povo e a ruína da cidade santa, e ficar aqui sentado enquanto ela é entregue nas mãos dos inimigos, e o santuário nas mãos de estrangeiros?"},
{v:8,t:"O seu templo tornou-se como um homem desonrado;"},
{v:9,t:"os seus objetos preciosos foram levados como presa; as suas crianças foram mortas nas praças, os seus jovens, pela espada do inimigo."},
{v:10,t:"Que nação não herdou o seu reino e não se apossou dos seus despojos?"},
{v:11,t:"Todos os seus adornos lhe foram arrancados; de livre que era, tornou-se escrava."},
{v:12,t:"Eis que o nosso santuário, a nossa beleza e a nossa glória foram devastados, e as nações os profanaram."},
{v:13,t:"Para que continuar vivendo?",np:1},
{v:14,t:"Matatias e os seus filhos rasgaram as vestes, vestiram-se de saco e fizeram grande luto."},
{s:"A revolta de Modin"},
{v:15,t:"Os oficiais do rei, encarregados de impor a apostasia, chegaram à cidade de Modin para fazer oferecer os sacrifícios."},
{v:16,t:"Muitos israelitas foram ter com eles; Matatias e os seus filhos também se reuniram ali."},
{v:17,t:"Os enviados do rei tomaram a palavra e disseram a Matatias: Tu és um chefe ilustre e poderoso nesta cidade, apoiado por filhos e irmãos."},
{v:18,t:"Aproxima-te, pois, tu primeiro e cumpre a ordem do rei, como fizeram todas as nações, os homens de Judá e os que ficaram em Jerusalém; e tu e a tua casa sereis contados entre os amigos do rei, e tu e os teus filhos sereis honrados com prata, ouro e muitos presentes.",n:"Amigos do rei: título oficial da corte selêucida."},
{v:19,t:"Matatias respondeu em alta voz: Ainda que todas as nações que estão no domínio do rei lhe obedeçam, abandonando cada uma o culto dos seus pais, e se submetam às suas ordens,"},
{v:20,t:"eu, os meus filhos e os meus irmãos seguiremos a aliança dos nossos pais."},
{v:21,t:"Deus nos livre de abandonar a Lei e os preceitos!"},
{v:22,t:"Não obedeceremos às ordens do rei, desviando-nos do nosso culto nem para a direita nem para a esquerda."},
{v:23,t:"Mal acabou de dizer estas palavras, um judeu se adiantou, à vista de todos, para oferecer sacrifício no altar de Modin, conforme a ordem do rei."},
{v:24,t:"Ao ver isso, Matatias inflamou-se de zelo, as suas entranhas estremeceram e deixou explodir uma justa ira: correu e o degolou sobre o altar.",n:"Nota do tradutor: O gesto de Matatias, que mata um compatriota no ato de sacrificar aos ídolos, é narrado como zelo pela Lei, à maneira de Fineias (Números 25,6–13). O texto não o atenua; reflete a gravidade que a idolatria tinha para a fé de Israel naquela hora de perseguição."},
{v:25,t:"Matou no mesmo instante o oficial do rei que obrigava a sacrificar e derrubou o altar."},
{v:26,t:"Assim mostrou o seu zelo pela Lei, como Fineias fez com Zambri, filho de Salu."},
{v:27,t:"Então Matatias gritou em alta voz pela cidade: Todo aquele que tem zelo pela Lei e se mantém fiel à aliança, venha comigo!"},
{v:28,t:"E fugiu com os seus filhos para as montanhas, deixando na cidade tudo o que possuíam."},
{s:"O massacre no deserto em dia de sábado"},
{v:29,t:"Então muitos que buscavam a justiça e o direito desceram ao deserto para morar ali,"},
{v:30,t:"eles, os seus filhos, as suas mulheres e os seus rebanhos, porque os males tinham caído pesadamente sobre eles."},
{v:31,t:"Os oficiais do rei e as tropas que estavam em Jerusalém, na Cidade de Davi, foram informados de que alguns homens que tinham desprezado a ordem do rei haviam descido aos esconderijos do deserto.",np:1},
{v:32,t:"Muitos correram atrás deles, alcançaram-nos, acamparam diante deles e prepararam-se para atacá-los no dia de sábado."},
{v:33,t:"E disseram-lhes: Basta! Saí, obedecei à ordem do rei e vivereis."},
{v:34,t:"Eles responderam: Não sairemos nem obedeceremos à ordem do rei, profanando o dia de sábado."},
{v:35,t:"Então os atacaram imediatamente."},
{v:36,t:"Mas eles não lhes responderam, nem lhes atiraram uma pedra, nem obstruíram os seus esconderijos;"},
{v:37,t:"diziam: Morramos todos na nossa inocência; o céu e a terra são testemunhas de que nos matais injustamente."},
{v:38,t:"Os inimigos os atacaram em pleno sábado, e morreram eles, as suas mulheres, os seus filhos e o seu gado: cerca de mil pessoas."},
{v:39,t:"Quando Matatias e os seus amigos o souberam, fizeram por eles um grande luto;",np:1},
{v:40,t:"e disseram uns aos outros: Se todos fizermos como os nossos irmãos fizeram, e não combatermos contra as nações pela nossa vida e pelos nossos preceitos, em pouco tempo nos farão desaparecer da terra."},
{v:41,t:"Naquele dia tomaram esta decisão: Se alguém vier atacar-nos em dia de sábado, combateremos contra ele, e não morreremos todos, como morreram os nossos irmãos nos esconderijos."},
{v:42,t:"Juntou-se a eles, então, a comunidade dos assideus, homens valentes de Israel, todos dedicados de coração à Lei.",n:"Assideus: em hebraico, hassidim, os piedosos, grupo de judeus fiéis de onde sairão mais tarde os fariseus e, talvez, os essênios."},
{v:43,t:"Todos os que fugiam dos males se uniram a eles e lhes deram apoio."},
{v:44,t:"Formaram um exército e feriram os pecadores na sua ira e os homens sem lei no seu furor; os que restaram fugiram para junto das nações, para se salvar.",np:1},
{v:45,t:"Matatias e os seus amigos percorreram o país e derrubaram os altares;",np:1},
{v:46,t:"circuncidaram à força todos os meninos incircuncisos que encontraram no território de Israel;"},
{v:47,t:"perseguiram os soberbos, e a obra prosperou nas suas mãos."},
{v:48,t:"Arrancaram a Lei das mãos das nações e das mãos dos reis, e não deixaram que o pecador prevalecesse."},
{s:"O testamento de Matatias"},
{v:49,t:"Quando se aproximaram os dias da sua morte, Matatias disse aos filhos: Agora triunfam a soberba e o insulto; é tempo de ruína e de ira furiosa."},
{v:50,t:"Agora, filhos, tende zelo pela Lei e dai a vida pela aliança dos nossos pais.",np:1},
{v:51,t:"Lembrai-vos das obras que os nossos pais realizaram no seu tempo, e alcançareis grande glória e um nome eterno."},
{v:52,t:"Abraão não foi achado fiel na provação, e isso não lhe foi contado como justiça?"},
{v:53,t:"José, no tempo da sua angústia, guardou o mandamento e tornou-se senhor do Egito."},
{v:54,t:"Fineias, nosso pai, pelo seu ardente zelo, recebeu a aliança de um sacerdócio eterno."},
{v:55,t:"Josué, por ter cumprido a palavra, tornou-se juiz em Israel."},
{v:56,t:"Caleb, por ter dado testemunho diante da assembleia, recebeu uma herança na terra."},
{v:57,t:"Davi, pela sua piedade, herdou o trono real para sempre."},
{v:58,t:"Elias, pelo seu ardente zelo pela Lei, foi arrebatado ao céu."},
{v:59,t:"Ananias, Azarias e Misael, por terem crido, foram salvos das chamas."},
{v:60,t:"Daniel, pela sua integridade, foi livrado da boca dos leões."},
{v:61,t:"Considerai, assim, de geração em geração: todos os que esperam nele não desfalecerão."},
{v:62,t:"Não temais as palavras do homem pecador, porque a sua glória acabará no esterco e nos vermes.",np:1},
{v:63,t:"Hoje se exalta, e amanhã já não será encontrado, porque terá voltado ao seu pó, e os seus projetos perecerão."},
{v:64,t:"E vós, filhos, sede fortes e corajosos na Lei, porque nela sereis glorificados.",np:1},
{v:65,t:"Aqui está Simão, vosso irmão: sei que é homem de conselho; escutai-o sempre; ele será para vós um pai."},
{v:66,t:"E Judas Macabeu, valente desde a juventude, será o chefe do vosso exército e conduzirá a guerra contra os povos."},
{v:67,t:"Reuni junto de vós todos os que praticam a Lei e vingai o vosso povo.",np:1},
{v:68,t:"Pagai às nações o que merecem e ficai atentos ao mandamento da Lei."},
{v:69,t:"Depois os abençoou e foi reunido aos seus pais.",np:1},
{v:70,t:"Morreu no ano cento e quarenta e seis e foi sepultado no túmulo dos seus pais, em Modin; e todo o Israel fez por ele um grande luto.",n:"Ano cento e quarenta e seis: 166 a.C."}
];

window.TEXTOS_SEED["1macabeus"][3] = [
{s:"O elogio de Judas Macabeu"},
{v:1,t:"Em seu lugar levantou-se o seu filho Judas, chamado Macabeu."},
{v:2,t:"Todos os seus irmãos e todos os que tinham seguido o seu pai o apoiavam, e combatiam com alegria as batalhas de Israel."},
{v:3,t:"Ele estendeu a glória do seu povo; vestiu a couraça como um gigante, cingiu as suas armas de guerra e travou batalhas, protegendo o acampamento com a espada."},
{v:4,t:"Nas suas façanhas era semelhante a um leão, a um leãozinho que ruge sobre a presa."},
{v:5,t:"Perseguiu os ímpios, procurando-os por toda parte, e entregou às chamas os que perturbavam o seu povo."},
{v:6,t:"Os ímpios se encolheram de medo diante dele, todos os que praticavam a iniquidade ficaram perturbados, e a salvação prosperou nas suas mãos."},
{v:7,t:"Causou amargura a muitos reis e alegrou Jacó com as suas façanhas; a sua memória será abençoada para sempre."},
{v:8,t:"Percorreu as cidades de Judá, exterminou delas os ímpios e afastou de Israel a ira."},
{v:9,t:"O seu nome chegou aos confins da terra, e ele reuniu os que estavam perdidos."},
{s:"As vitórias sobre Apolônio e Seron"},
{v:10,t:"Apolônio reuniu gente das nações e um grande exército da Samaria para combater contra Israel."},
{v:11,t:"Ao saber disso, Judas saiu ao seu encontro, derrotou-o e o matou. Muitos caíram mortos, e os restantes fugiram."},
{v:12,t:"Recolheram os seus despojos; Judas ficou com a espada de Apolônio e combateu com ela todos os dias da sua vida."},
{v:13,t:"Seron, comandante do exército da Síria, soube que Judas tinha reunido em torno de si uma multidão, uma assembleia de fiéis prontos para a guerra,"},
{v:14,t:"e disse: Vou fazer um nome e cobrir-me de glória no reino: combaterei Judas e os seus companheiros, que desprezam as ordens do rei."},
{v:15,t:"Preparou-se, e com ele subiu um forte exército de ímpios, para ajudá-lo a vingar-se dos filhos de Israel."},
{v:16,t:"Chegou à subida de Bet-Horon, e Judas saiu ao seu encontro com poucos homens."},
{v:17,t:"Quando viram o exército que vinha contra eles, disseram a Judas: Como poderemos, sendo tão poucos, combater contra uma multidão tão numerosa e forte? E nós estamos esgotados, porque hoje não comemos nada."},
{v:18,t:"Judas respondeu: É fácil que muitos caiam nas mãos de poucos; para o Céu não há diferença entre salvar com muitos ou com poucos,",n:"O Céu: modo respeitoso de designar Deus, frequente neste livro, que evita pronunciar o seu nome."},
{v:19,t:"porque a vitória na guerra não depende do tamanho do exército, mas a força vem do Céu."},
{v:20,t:"Eles vêm contra nós cheios de insolência e de iniquidade, para nos exterminar, a nós, às nossas mulheres e aos nossos filhos, e para nos saquear;",np:1},
{v:21,t:"nós, porém, combatemos pela nossa vida e pelas nossas leis."},
{v:22,t:"Ele mesmo os esmagará diante de nós; não tenhais medo deles."},
{v:23,t:"Quando acabou de falar, lançou-se de surpresa sobre eles, e Seron e o seu exército foram esmagados diante dele."},
{v:24,t:"Perseguiram-no pela descida de Bet-Horon até a planície; caíram uns oitocentos deles, e os restantes fugiram para a terra dos filisteus."},
{v:25,t:"Judas e os seus irmãos começaram a ser temidos, e o pavor caiu sobre as nações ao redor."},
{v:26,t:"A sua fama chegou até o rei, e todas as nações falavam das batalhas de Judas."},
{s:"Antíoco parte para a Pérsia"},
{v:27,t:"Quando o rei Antíoco ouviu essas notícias, enfureceu-se; mandou reunir todas as forças do seu reino, um exército muito poderoso."},
{v:28,t:"Abriu o seu tesouro, pagou às tropas o soldo de um ano e ordenou-lhes que estivessem prontas para qualquer necessidade."},
{v:29,t:"Mas viu que o dinheiro faltava nos seus cofres e que os tributos da região eram poucos, por causa da discórdia e da calamidade que ele mesmo provocara na terra, ao abolir as leis que vigoravam desde os tempos antigos;"},
{v:30,t:"e teve medo de não ter, como já acontecera uma ou duas vezes, com que pagar as despesas e os presentes que antes distribuía com mão generosa, superando nisso os reis que o precederam."},
{v:31,t:"Muito perplexo, decidiu ir à Pérsia para cobrar os tributos daquelas regiões e juntar muito dinheiro."},
{v:32,t:"Deixou Lísias, homem ilustre e de linhagem real, à frente dos negócios do rei, desde o rio Eufrates até a fronteira do Egito,"},
{v:33,t:"e encarregado de educar o seu filho Antíoco até a sua volta."},
{v:34,t:"Entregou-lhe metade das tropas e os elefantes, e deu-lhe instruções sobre tudo o que queria, especialmente sobre os habitantes da Judeia e de Jerusalém:"},
{v:35,t:"que enviasse contra eles um exército para esmagar e aniquilar a força de Israel e o que restava de Jerusalém, e apagar deste lugar a sua memória;"},
{v:36,t:"que estabelecesse estrangeiros em todo o seu território e distribuísse a sua terra em lotes."},
{v:37,t:"O rei tomou a outra metade das tropas e partiu de Antioquia, capital do seu reino, no ano cento e quarenta e sete; atravessou o rio Eufrates e percorreu as províncias altas.",n:"Ano cento e quarenta e sete: 165 a.C. As províncias altas são as do planalto do Irã."},
{s:"A expedição de Nicanor e Górgias"},
{v:38,t:"Lísias escolheu Ptolomeu, filho de Dorímenes, Nicanor e Górgias, homens poderosos entre os amigos do rei,"},
{v:39,t:"e enviou com eles quarenta mil homens e sete mil cavaleiros, para invadirem a terra de Judá e a devastarem, conforme a ordem do rei."},
{v:40,t:"Partiram com todas as suas tropas e vieram acampar perto de Emaús, na planície."},
{v:41,t:"Os mercadores da região ouviram falar deles; tomaram muita prata e muito ouro, e também grilhões, e foram ao acampamento para comprar os filhos de Israel como escravos. Juntaram-se a eles tropas da Síria e da terra dos estrangeiros.",n:"Síria: talvez se deva ler Edom, porque em hebraico as duas palavras se parecem. A terra dos estrangeiros é a Filisteia."},
{v:42,t:"Judas e os seus irmãos viram que os males se multiplicavam e que os exércitos acampavam no seu território; souberam também das ordens do rei, que mandara destruir e exterminar o povo.",np:1},
{v:43,t:"E disseram uns aos outros: Reergamos o nosso povo da sua ruína e combatamos pelo nosso povo e pelo santuário."},
{v:44,t:"Reuniu-se a assembleia, para se preparar para a guerra, para rezar e pedir misericórdia e compaixão."},
{v:45,t:"Jerusalém estava despovoada como um deserto; nenhum dos seus filhos entrava nem saía. O santuário era pisado, estrangeiros ocupavam a Cidadela, feita pousada das nações. A alegria desaparecera de Jacó, calaram-se a flauta e a cítara.",np:1},
{s:"A assembleia de Masfa"},
{v:46,t:"Reuniram-se e foram a Masfa, em frente a Jerusalém, porque antigamente Masfa era para Israel um lugar de oração."},
{v:47,t:"Jejuaram naquele dia, vestiram-se de saco, puseram cinza sobre a cabeça e rasgaram as vestes."},
{v:48,t:"Abriram o livro da Lei para nele buscar aquilo que os pagãos procuravam junto às imagens dos seus ídolos.",n:"Frase obscura. Talvez queira dizer que os judeus consultaram a Lei, como os pagãos consultavam os seus ídolos; outros entendem que os pagãos pintavam figuras dos seus ídolos nos livros da Lei."},
{v:49,t:"Trouxeram as vestes sacerdotais, as primícias e os dízimos, e fizeram vir os nazireus que tinham completado os dias do seu voto;"},
{v:50,t:"e clamaram em alta voz ao Céu: Que faremos com estes, e para onde os levaremos?",n:"Sem o templo, não havia como oferecer as primícias e os dízimos, nem como concluir o voto dos nazireus (Números 6,13–20)."},
{v:51,t:"O teu santuário foi pisado e profanado, e os teus sacerdotes estão de luto e humilhados."},
{v:52,t:"Eis que as nações se reuniram contra nós para nos exterminar; tu sabes o que tramam contra nós."},
{v:53,t:"Como poderemos resistir diante deles, se tu não nos ajudares?"},
{v:54,t:"Tocaram as trombetas e gritaram em alta voz."},
{v:55,t:"Depois disso, Judas nomeou chefes do povo: chefes de mil, de cem, de cinquenta e de dez."},
{v:56,t:"Aos que estavam construindo casa, aos que estavam noivos, aos que tinham plantado vinha e aos medrosos, disse que voltasse cada um para a sua casa, conforme a Lei.",n:"Veja Deuteronômio 20,5–8."},
{v:57,t:"Então o exército partiu e acampou ao sul de Emaús."},
{v:58,t:"Judas disse: Cingi-vos, sede valentes e estai prontos, amanhã de manhã, para combater contra essas nações que se reuniram contra nós para nos exterminar, a nós e ao nosso santuário."},
{v:59,t:"Porque é melhor morrermos combatendo do que ver as desgraças do nosso povo e do santuário."},
{v:60,t:"Seja qual for a vontade do Céu, ele a cumprirá."}
];

window.TEXTOS_SEED["1macabeus"][4] = [
{s:"A vitória de Emaús"},
{v:1,t:"Górgias tomou cinco mil homens e mil cavaleiros escolhidos, e o destacamento partiu de noite,"},
{v:2,t:"para cair sobre o acampamento dos judeus e atacá-los de surpresa; os homens da Cidadela lhe serviam de guias."},
{v:3,t:"Judas soube disso e partiu com os seus valentes, para atacar o exército do rei que estava em Emaús,"},
{v:4,t:"enquanto as tropas ainda estavam dispersas fora do acampamento."},
{v:5,t:"Górgias chegou de noite ao acampamento de Judas e não encontrou ninguém; então foi procurá-los nas montanhas, pensando: Estes fogem de nós."},
{v:6,t:"Ao romper do dia, Judas apareceu na planície com três mil homens, que não tinham as armaduras e as espadas que desejariam."},
{v:7,t:"Viram o acampamento dos pagãos, forte e bem armado, com a cavalaria ao redor, gente adestrada para a guerra."},
{v:8,t:"Judas disse aos homens que estavam com ele: Não temais a sua multidão, nem vos assusteis com o seu ataque."},
{v:9,t:"Lembrai-vos de como os nossos pais foram salvos no mar Vermelho, quando o faraó os perseguia com o seu exército."},
{v:10,t:"Clamemos agora ao Céu, para ver se ele terá compaixão de nós, se lembrará da aliança dos nossos pais e esmagará hoje este exército diante de nós."},
{v:11,t:"E todas as nações saberão que há quem resgate e salve Israel."},
{v:12,t:"Os estrangeiros ergueram os olhos e viram que eles vinham ao seu encontro;",np:1},
{v:13,t:"saíram do acampamento para a batalha. Os homens de Judas tocaram as trombetas"},
{v:14,t:"e travaram combate; os pagãos foram derrotados e fugiram para a planície."},
{v:15,t:"Todos os da retaguarda caíram pela espada. Perseguiram-nos até Gazer e até as planícies da Idumeia, de Azoto e de Jâmnia; e caíram deles uns três mil homens.",np:1},
{v:16,t:"Judas e o exército voltaram da perseguição,"},
{v:17,t:"e ele disse ao povo: Não cobiceis o saque, porque temos ainda uma batalha pela frente:"},
{v:18,t:"Górgias e o seu exército estão perto de nós, na montanha. Enfrentai agora os nossos inimigos e combatei-os; depois recolhereis o saque com segurança."},
{v:19,t:"Judas ainda estava falando quando apareceu um destacamento, espreitando do alto da montanha."},
{v:20,t:"Viram que os seus tinham sido postos em fuga e que o acampamento estava sendo incendiado; a fumaça que se via mostrava o que tinha acontecido."},
{v:21,t:"Diante disso, ficaram apavorados; e, vendo também o exército de Judas na planície, pronto para o combate,",np:1},
{v:22,t:"fugiram todos para a terra dos estrangeiros."},
{v:23,t:"Judas voltou para saquear o acampamento; recolheram muito ouro e prata, tecidos de púrpura violeta e de púrpura marinha, e grandes riquezas.",np:1},
{v:24,t:"Na volta, cantavam hinos e bendiziam o Céu: Porque ele é bom, porque o seu amor é para sempre."},
{v:25,t:"Naquele dia houve uma grande salvação para Israel."},
{s:"A vitória sobre Lísias em Bet-Sur"},
{v:26,t:"Os estrangeiros que escaparam foram contar a Lísias tudo o que tinha acontecido."},
{v:27,t:"Ao ouvir isso, ele ficou consternado e desanimado, porque as coisas não tinham acontecido em Israel como ele queria, nem saíram como o rei lhe ordenara."},
{v:28,t:"No ano seguinte, reuniu sessenta mil homens escolhidos e cinco mil cavaleiros, para acabar com eles.",np:1},
{v:29,t:"Vieram pela Idumeia e acamparam em Bet-Sur; Judas saiu ao seu encontro com dez mil homens."},
{v:30,t:"Vendo aquele exército poderoso, rezou assim: Bendito és tu, Salvador de Israel, que quebraste o ímpeto do guerreiro poderoso pela mão do teu servo Davi e entregaste o acampamento dos filisteus nas mãos de Jônatas, filho de Saul, e do seu escudeiro."},
{v:31,t:"Entrega também este exército nas mãos do teu povo, Israel, e que fiquem envergonhados com as suas tropas e a sua cavalaria."},
{v:32,t:"Infunde-lhes medo, derrete a audácia da sua força, e que vacilem na sua derrota."},
{v:33,t:"Abate-os pela espada dos que te amam, e que todos os que conhecem o teu nome te louvem com hinos."},
{v:34,t:"Travou-se o combate, e caíram do exército de Lísias uns cinco mil homens, abatidos diante deles.",np:1},
{v:35,t:"Quando Lísias viu a derrota das suas tropas e a coragem das de Judas, e como estavam prontos para viver ou morrer com valentia, voltou para Antioquia e recrutou mercenários, para voltar à Judeia com forças ainda maiores.",n:"Segundo 2 Macabeus 11,13–15, Lísias fez então um acordo de paz com os judeus."},
{s:"A purificação do templo"},
{v:36,t:"Então Judas e os seus irmãos disseram: Os nossos inimigos foram esmagados; subamos para purificar o santuário e consagrá-lo de novo."},
{v:37,t:"Todo o exército se reuniu, e subiram ao monte Sião.",np:1},
{v:38,t:"Viram o santuário abandonado, o altar profanado, as portas queimadas, e nos pátios o mato crescido como num bosque ou num monte, e as salas dos sacerdotes em ruínas."},
{v:39,t:"Rasgaram as vestes, fizeram grande lamentação, cobriram-se de cinza"},
{v:40,t:"e prostraram-se com o rosto em terra; tocaram as trombetas de sinal e clamaram ao Céu."},
{v:41,t:"Então Judas ordenou a alguns homens que combatessem os da Cidadela, até que ele terminasse de purificar o santuário."},
{v:42,t:"Escolheu sacerdotes sem defeito, dedicados à Lei,",np:1},
{v:43,t:"que purificaram o santuário e levaram para um lugar impuro as pedras da profanação."},
{v:44,t:"Discutiram o que fazer com o altar dos holocaustos, que tinha sido profanado,"},
{v:45,t:"e tiveram a boa ideia de demoli-lo, para que não lhes fosse motivo de vergonha, pois os pagãos o tinham contaminado. Demoliram, pois, o altar"},
{v:46,t:"e guardaram as pedras no monte do templo, num lugar conveniente, até que surgisse um profeta que decidisse o que fazer com elas."},
{v:47,t:"Tomaram pedras não lavradas, conforme a Lei, e construíram um altar novo, semelhante ao anterior.",n:"Pedras não lavradas: veja Êxodo 20,25 e Deuteronômio 27,5–6."},
{v:48,t:"Restauraram o santuário e o interior do templo, e consagraram os pátios."},
{v:49,t:"Fizeram novos objetos sagrados e levaram para dentro do templo o candelabro, o altar dos perfumes e a mesa.",np:1},
{v:50,t:"Queimaram incenso sobre o altar e acenderam as lâmpadas do candelabro, que iluminaram o templo."},
{v:51,t:"Puseram os pães sobre a mesa e penduraram as cortinas. Assim terminaram todas as obras que tinham empreendido."},
{s:"A dedicação do altar"},
{v:52,t:"No dia vinte e cinco do nono mês, que é o mês de Casleu, do ano cento e quarenta e oito, levantaram-se de madrugada",n:"Ano cento e quarenta e oito: dezembro de 164 a.C., três anos depois da profanação (1,54)."},
{v:53,t:"e ofereceram o sacrifício, conforme a Lei, sobre o novo altar dos holocaustos que tinham construído."},
{v:54,t:"No mesmo tempo e no mesmo dia em que os pagãos o tinham profanado, o altar foi consagrado de novo, com cânticos, cítaras, harpas e címbalos."},
{v:55,t:"Todo o povo se prostrou com o rosto em terra, adorou e bendisse o Céu, que lhes tinha dado a vitória.",np:1},
{v:56,t:"Celebraram durante oito dias a consagração do altar, oferecendo com alegria holocaustos e sacrifícios de comunhão e de louvor."},
{v:57,t:"Adornaram a fachada do templo com coroas de ouro e pequenos escudos, restauraram as portas e as salas dos sacerdotes e puseram-lhes portas."},
{v:58,t:"Houve imensa alegria entre o povo, e foi apagada a afronta dos pagãos."},
{v:59,t:"Judas, os seus irmãos e toda a assembleia de Israel determinaram que os dias da consagração do altar fossem celebrados a seu tempo, todos os anos, durante oito dias, a partir do dia vinte e cinco do mês de Casleu, com alegria e júbilo.",np:1,n:"É a festa da Dedicação, em hebraico Hanucá, que Jesus celebrou em Jerusalém (João 10,22)."},
{v:60,t:"Naquele tempo, cercaram o monte Sião de muralhas altas e torres fortes, para que os pagãos não viessem pisá-lo, como tinham feito antes."},
{v:61,t:"Judas deixou ali uma guarnição para defendê-lo; fortificou também Bet-Sur, para que o povo tivesse uma fortaleza diante da Idumeia."}
];

window.TEXTOS_SEED["1macabeus"][5] = [
{s:"Guerras contra os povos vizinhos"},
{v:1,t:"Quando as nações ao redor souberam que o altar tinha sido reconstruído e o santuário consagrado de novo como antes, ficaram muito irritadas"},
{v:2,t:"e resolveram exterminar os da raça de Jacó que viviam no meio delas; e começaram a matar e a destruir gente do povo."},
{v:3,t:"Judas combateu contra os filhos de Esaú na Idumeia, em Acrabatena, porque cercavam Israel; infligiu-lhes uma grande derrota, abateu-os e tomou os seus despojos."},
{v:4,t:"Lembrou-se também da maldade dos filhos de Bean, que eram para o povo um laço e uma armadilha, emboscando-o nos caminhos."},
{v:5,t:"Encurralou-os nas suas torres, sitiou-os, votou-os ao extermínio e incendiou as torres com todos os que estavam dentro.",n:"Nota do tradutor: Votar ao extermínio traduz o antigo herem, a lei de guerra que consagrava a Deus, pela destruição total, o inimigo vencido (Deuteronômio 20,16–18; Josué 6,17). O livro narra estas campanhas, com a matança dos homens e o incêndio das cidades (5,28.35.44.51), sem as atenuar."},
{v:6,t:"Depois passou contra os amonitas, onde encontrou uma força poderosa e muita gente, comandada por Timóteo."},
{v:7,t:"Travou com eles muitos combates; foram esmagados diante dele, e ele os derrotou."},
{v:8,t:"Tomou Jazer e as suas aldeias e voltou para a Judeia."},
{s:"Pedidos de socorro de Galaad e da Galileia"},
{v:9,t:"As nações de Galaad se coligaram contra os israelitas que viviam no seu território, para exterminá-los; e estes se refugiaram na fortaleza de Datema."},
{v:10,t:"Enviaram cartas a Judas e aos seus irmãos, dizendo: As nações ao redor se coligaram contra nós para nos exterminar;"},
{v:11,t:"preparam-se para vir tomar a fortaleza em que nos refugiamos, e Timóteo comanda o seu exército."},
{v:12,t:"Vem, pois, agora e livra-nos das suas mãos, porque muitos de nós já caíram;"},
{v:13,t:"todos os nossos irmãos que viviam na região de Tubin foram mortos; levaram cativas as suas mulheres e os seus filhos, com os seus bens, e mataram ali cerca de mil homens.",n:"No grego, na terra de Tobias, região a leste do Jordão."},
{v:14,t:"Ainda estavam lendo essas cartas, quando chegaram da Galileia outros mensageiros, com as vestes rasgadas, trazendo notícias semelhantes.",np:1},
{v:15,t:"Diziam: Os de Ptolemaida, de Tiro e de Sidônia, e toda a Galileia dos estrangeiros, se coligaram contra nós para nos exterminar."},
{v:16,t:"Quando Judas e o povo ouviram essas notícias, reuniu-se uma grande assembleia para decidir o que fazer pelos seus irmãos, que estavam em aflição e eram atacados pelos inimigos."},
{v:17,t:"Judas disse ao seu irmão Simão: Escolhe homens e vai libertar os teus irmãos da Galileia; eu e o meu irmão Jônatas iremos à região de Galaad."},
{v:18,t:"Deixou José, filho de Zacarias, e Azarias, chefe do povo, com o restante do exército na Judeia, para guardá-la,"},
{v:19,t:"e deu-lhes esta ordem: Tomai conta deste povo e não entreis em combate com as nações até que voltemos.",np:1},
{v:20,t:"Foram destinados três mil homens a Simão, para ir à Galileia, e oito mil a Judas, para a região de Galaad."},
{v:21,t:"Simão foi à Galileia e travou muitos combates com as nações, que foram esmagadas diante dele;",np:1},
{v:22,t:"perseguiu-as até a porta de Ptolemaida. Caíram uns três mil homens das nações, e ele tomou os seus despojos."},
{v:23,t:"Tomou consigo os judeus da Galileia e de Arbates, com as mulheres, os filhos e tudo o que possuíam, e levou-os para a Judeia com grande alegria."},
{s:"Judas em Galaad"},
{v:24,t:"Judas Macabeu e o seu irmão Jônatas atravessaram o Jordão e caminharam três dias pelo deserto."},
{v:25,t:"Encontraram os nabateus, que os receberam em paz e lhes contaram tudo o que acontecera aos seus irmãos na região de Galaad:"},
{v:26,t:"que muitos deles estavam cercados em Bosora e em Bosor, em Alema, em Casfo, em Maced e em Carnaim, todas cidades fortificadas e grandes;"},
{v:27,t:"que outros estavam cercados nas demais cidades de Galaad; e que os inimigos tinham decidido atacar as fortalezas no dia seguinte, tomá-las e exterminar todos num só dia."},
{v:28,t:"Judas e o seu exército mudaram de rumo de repente e foram pelo deserto até Bosora; tomaram a cidade, passaram ao fio da espada todos os homens, levaram todos os despojos e a incendiaram."},
{v:29,t:"Partiram dali de noite e marcharam até a fortaleza."},
{v:30,t:"Ao amanhecer, levantaram os olhos e viram uma multidão incontável, com escadas e máquinas de guerra, para tomar a fortaleza; já estavam atacando os que estavam dentro."},
{v:31,t:"Judas viu que o combate tinha começado e que o clamor da cidade subia ao céu, com trombetas e grandes gritos;"},
{v:32,t:"e disse aos homens do seu exército: Combatei hoje pelos nossos irmãos!"},
{v:33,t:"Avançou em três colunas pela retaguarda dos inimigos; tocaram as trombetas e clamaram em oração."},
{v:34,t:"O exército de Timóteo reconheceu que era o Macabeu e fugiu diante dele; Judas infligiu-lhes uma grande derrota, e naquele dia caíram deles uns oito mil homens."},
{v:35,t:"Depois Judas se desviou para Masfa, atacou-a e tomou-a; matou todos os seus homens, tomou os despojos e a incendiou.",n:"Masfa: assim a Nova Vulgata, com parte dos manuscritos gregos; outros leem Alema."},
{v:36,t:"De lá partiu e tomou Casfo, Maced, Bosor e as outras cidades de Galaad."},
{v:37,t:"Depois desses acontecimentos, Timóteo reuniu outro exército e acampou diante de Rafon, do outro lado da torrente."},
{v:38,t:"Judas mandou espiar o acampamento, e os espiões lhe informaram: Todas as nações ao nosso redor se juntaram a ele, um exército muito numeroso;"},
{v:39,t:"contrataram também árabes para os ajudar, e estão acampados do outro lado da torrente, prontos para vir atacar-te. Judas saiu ao encontro deles."},
{v:40,t:"Timóteo disse aos comandantes do seu exército: Quando Judas e o seu exército chegarem à torrente, se ele passar primeiro para o nosso lado, não conseguiremos resistir-lhe, porque certamente nos vencerá;"},
{v:41,t:"mas, se tiver medo e acampar do outro lado do rio, atravessaremos até ele e o venceremos."},
{v:42,t:"Quando Judas chegou à torrente, pôs os escribas do povo à beira da água e deu-lhes esta ordem: Não deixeis ninguém ficar acampado; que todos venham para o combate."},
{v:43,t:"Ele foi o primeiro a atravessar contra eles, e todo o povo atrás dele. Todas as nações foram esmagadas diante deles; largaram as armas e fugiram para o santuário pagão de Carnaim."},
{v:44,t:"Tomaram a cidade e incendiaram o santuário com todos os que estavam dentro. Carnaim foi abatida e não pôde mais resistir diante de Judas."},
{v:45,t:"Judas reuniu todos os israelitas que estavam na região de Galaad, do menor ao maior, com as mulheres, os filhos e os bens, uma caravana muito grande, para irem à terra de Judá."},
{v:46,t:"Chegaram a Efron, cidade grande e muito fortificada, situada no caminho; não havia como desviar-se dela, nem pela direita nem pela esquerda: era preciso passar pelo meio dela."},
{v:47,t:"Mas os habitantes da cidade fecharam-se dentro e obstruíram as portas com pedras. Judas mandou-lhes mensageiros com palavras de paz,",np:1},
{v:48,t:"dizendo: Deixai-nos passar pela vossa terra, para irmos à nossa; ninguém vos fará mal, só passaremos a pé. Mas eles não quiseram abrir-lhe as portas."},
{v:49,t:"Então Judas mandou anunciar no acampamento que cada um tomasse posição onde estava."},
{v:50,t:"Os guerreiros tomaram posição, e ele atacou a cidade durante todo aquele dia e toda a noite; e a cidade lhe foi entregue nas mãos."},
{v:51,t:"Passou ao fio da espada todos os homens, arrasou a cidade, tomou os seus despojos e atravessou-a por cima dos cadáveres."},
{v:52,t:"Atravessaram o Jordão para a grande planície, diante de Bet-San."},
{v:53,t:"Durante todo o caminho, Judas ia reunindo os que ficavam para trás e animando o povo, até chegarem à terra de Judá."},
{v:54,t:"Subiram ao monte Sião com alegria e júbilo e ofereceram holocaustos, porque nenhum deles tinha caído até voltarem em paz."},
{s:"A derrota de José e Azarias"},
{v:55,t:"Enquanto Judas e Jônatas estavam na terra de Galaad, e o seu irmão Simão na Galileia, diante de Ptolemaida,"},
{v:56,t:"José, filho de Zacarias, e Azarias, comandantes do exército, ouviram falar das façanhas e dos combates que eles tinham realizado,"},
{v:57,t:"e disseram: Façamos também nós um nome; vamos combater as nações ao nosso redor."},
{v:58,t:"Deram ordens às tropas que estavam com eles e marcharam contra Jâmnia."},
{v:59,t:"Górgias saiu da cidade com os seus homens para combatê-los."},
{v:60,t:"José e Azarias foram derrotados e perseguidos até a fronteira da Judeia; naquele dia caíram do povo de Israel uns dois mil homens. Foi uma grande derrota para o povo,"},
{v:61,t:"porque não tinham obedecido a Judas e aos seus irmãos, julgando que fariam proezas."},
{v:62,t:"Mas eles não eram da estirpe daqueles homens a quem fora confiada a salvação de Israel."},
{s:"Novas vitórias de Judas"},
{v:63,t:"O valente Judas e os seus irmãos foram muito honrados diante de todo o Israel e de todas as nações aonde chegava a sua fama;"},
{v:64,t:"e as pessoas acorriam a eles para os aclamar."},
{v:65,t:"Judas e os seus irmãos saíram para combater os filhos de Esaú na terra do sul. Tomou Hebron e as suas aldeias, demoliu as suas fortificações e incendiou as torres ao redor."},
{v:66,t:"Depois partiu para a terra dos filisteus e atravessou Maresa."},
{v:67,t:"Naquele dia caíram em combate alguns sacerdotes que, querendo mostrar a sua valentia, saíram imprudentemente para a batalha."},
{v:68,t:"Judas desviou-se para Azoto, na terra dos filisteus; derrubou os seus altares, queimou as imagens esculpidas dos seus deuses, saqueou as cidades e voltou para a terra de Judá."}
];

window.TEXTOS_SEED["1macabeus"][6] = [
{s:"A morte de Antíoco Epífanes"},
{v:1,t:"Enquanto isso, o rei Antíoco percorria as províncias altas. Soube que na Pérsia havia uma cidade chamada Elimaida, famosa pelas suas riquezas, pela prata e pelo ouro,",n:"Elimaida era na verdade uma região, no sudoeste do Irã. Ali Antíoco tentou saquear um templo e morreu pouco depois, em 164 a.C.; 2 Macabeus 1,13–17 e 9,1–29 contam a sua morte de outros modos."},
{v:2,t:"e que o seu templo era muito rico, com adornos de ouro, couraças e armas que ali deixara Alexandre, filho de Filipe, o rei macedônio, o primeiro a reinar sobre os gregos."},
{v:3,t:"Foi até lá e tentou tomar a cidade e saqueá-la, mas não conseguiu, porque os habitantes da cidade souberam do seu plano",np:1},
{v:4,t:"e o enfrentaram em combate. Ele fugiu e partiu dali, muito abatido, para voltar à Babilônia."},
{v:5,t:"Ainda na Pérsia, chegou-lhe um mensageiro com a notícia de que os exércitos enviados à terra de Judá tinham sido derrotados;"},
{v:6,t:"que Lísias, que fora à frente com um exército poderoso, tinha recuado diante deles; que os judeus se tinham fortalecido com as armas, as tropas e os muitos despojos tomados dos exércitos que tinham destroçado;"},
{v:7,t:"que tinham derrubado a abominação que ele erigira sobre o altar de Jerusalém, e que tinham cercado o santuário de muralhas altas, como antes, e também Bet-Sur, uma das suas cidades."},
{v:8,t:"Ao ouvir essas notícias, o rei ficou consternado e profundamente abalado; caiu de cama e adoeceu de tristeza, porque as coisas não tinham acontecido como ele queria."},
{v:9,t:"Ficou ali muitos dias, porque uma grande tristeza voltava sempre a tomá-lo, e pensou que ia morrer."},
{v:10,t:"Chamou todos os seus amigos e disse-lhes: O sono foge dos meus olhos, e o meu coração desfalece de preocupação."},
{v:11,t:"E disse comigo: A que aflição cheguei, e em que grande tormenta estou agora! Eu, que era bondoso e amado no meu poder!"},
{v:12,t:"Mas agora me lembro dos males que fiz em Jerusalém: levei todos os objetos de prata e de ouro que havia nela e mandei exterminar sem motivo os habitantes de Judá."},
{v:13,t:"Reconheço que é por isso que me sobrevieram esses males; e eis que morro de profunda tristeza em terra estrangeira."},
{v:14,t:"Chamou Filipe, um dos seus amigos, e o pôs à frente de todo o seu reino;"},
{v:15,t:"deu-lhe o diadema, o manto e o anel, para que conduzisse o seu filho Antíoco e o educasse para reinar."},
{v:16,t:"E o rei Antíoco morreu ali, no ano cento e quarenta e nove.",n:"Ano cento e quarenta e nove: 164–163 a.C."},
{v:17,t:"Quando Lísias soube que o rei tinha morrido, pôs no trono o filho dele, Antíoco, que ele educara desde menino, e deu-lhe o nome de Eupátor."},
{s:"O cerco da Cidadela"},
{v:18,t:"Os que ocupavam a Cidadela mantinham Israel encurralado ao redor do santuário e procuravam sempre fazer-lhe mal, servindo de apoio aos pagãos."},
{v:19,t:"Judas decidiu acabar com eles e convocou todo o povo para sitiá-los."},
{v:20,t:"Reuniram-se e sitiaram a Cidadela no ano cento e cinquenta; e construíram plataformas de tiro e máquinas de guerra.",n:"Ano cento e cinquenta: 163–162 a.C."},
{v:21,t:"Mas alguns dos sitiados escaparam, e juntaram-se a eles alguns ímpios de Israel;"},
{v:22,t:"foram ter com o rei e disseram: Até quando deixarás de fazer justiça e de vingar os nossos irmãos?"},
{v:23,t:"Nós aceitamos de boa vontade servir o teu pai, seguir as suas palavras e obedecer aos seus decretos."},
{v:24,t:"Por isso os filhos do nosso povo sitiaram a Cidadela e se tornaram nossos inimigos; mataram todos os nossos que encontraram e saquearam as nossas herdades."},
{v:25,t:"E não levantaram a mão só contra nós, mas também contra todo o território vizinho."},
{v:26,t:"Eis que hoje estão sitiando a Cidadela de Jerusalém para tomá-la; e fortificaram o santuário e Bet-Sur."},
{v:27,t:"Se não te antecipares a eles depressa, farão coisas ainda piores, e não poderás mais contê-los."},
{s:"A batalha de Bet-Zacarias"},
{v:28,t:"Ao ouvir isso, o rei enfureceu-se e reuniu todos os seus amigos, os comandantes do seu exército e os chefes da cavalaria."},
{v:29,t:"Vieram-lhe também tropas mercenárias de outros reinos e das ilhas do mar."},
{v:30,t:"O seu exército contava cem mil soldados de infantaria, vinte mil cavaleiros e trinta e dois elefantes adestrados para a guerra."},
{v:31,t:"Vieram pela Idumeia e acamparam diante de Bet-Sur; atacaram-na durante muitos dias e construíram máquinas de guerra; mas os sitiados saíram, incendiaram-nas e combateram com valentia."},
{v:32,t:"Então Judas retirou-se da Cidadela e acampou em Bet-Zacarias, diante do acampamento do rei."},
{v:33,t:"O rei levantou-se de madrugada e lançou o exército em marcha acelerada pelo caminho de Bet-Zacarias; as tropas se dispuseram para a batalha e tocaram as trombetas."},
{v:34,t:"Mostraram aos elefantes suco de uva e de amoras, para excitá-los ao combate."},
{v:35,t:"Distribuíram os animais pelas falanges; junto de cada elefante puseram mil homens com cotas de malha e capacetes de bronze na cabeça, e para cada animal foram destacados quinhentos cavaleiros escolhidos.",np:1},
{v:36,t:"Estes estavam sempre onde estava o animal e iam aonde ele ia, sem se afastar dele."},
{v:37,t:"Sobre cada animal havia uma torre de madeira, forte e coberta, presa a ele com correias; em cada torre iam quatro guerreiros, que combatiam de cima, além do condutor indiano."},
{v:38,t:"O restante da cavalaria, o rei o dispôs de um lado e do outro, nos dois flancos do exército, para inquietar o inimigo e proteger as falanges."},
{v:39,t:"Quando o sol brilhou sobre os escudos de ouro e de bronze, as montanhas resplandeceram com eles e brilharam como tochas acesas."},
{v:40,t:"Uma parte do exército do rei estendeu-se pelas alturas, e outra pelas partes baixas; e avançavam com segurança e em boa ordem."},
{v:41,t:"Todos os que ouviam o clamor daquela multidão, o marchar da tropa e o entrechocar das armas tremiam, porque o exército era imenso e poderoso."},
{v:42,t:"Judas e o seu exército avançaram para o combate, e caíram do exército do rei seiscentos homens.",np:1},
{v:43,t:"Eleazar, chamado Abaran, viu um dos animais coberto com a couraça real, mais alto que todos os outros, e pensou que nele estivesse o rei.",np:1},
{v:44,t:"Então se entregou à morte para salvar o seu povo e conquistar para si um nome eterno."},
{v:45,t:"Correu com audácia contra ele, pelo meio da falange, matando à direita e à esquerda, e os inimigos se abriam diante dele de um lado e de outro."},
{v:46,t:"Meteu-se debaixo do elefante, feriu-o por baixo e o matou; o animal caiu por terra sobre ele, e ele morreu ali."},
{v:47,t:"Os judeus, vendo a força do reino e o ímpeto das tropas, retiraram-se diante delas.",np:1},
{s:"O cerco do monte Sião"},
{v:48,t:"O exército do rei subiu atrás deles até Jerusalém, e o rei acampou contra a Judeia e contra o monte Sião."},
{v:49,t:"Fez as pazes com os de Bet-Sur, que saíram da cidade porque não tinham ali víveres para suportar o cerco, pois era um ano sabático para a terra.",n:"Ano sabático: a cada sete anos, a terra devia ficar em descanso, sem ser cultivada (Levítico 25,1–7)."},
{v:50,t:"O rei ocupou Bet-Sur e deixou ali uma guarnição para guardá-la."},
{v:51,t:"Depois sitiou o santuário durante muitos dias; montou ali plataformas de tiro, máquinas de guerra, lança-chamas, catapultas, escorpiões para disparar flechas e fundas."},
{v:52,t:"Os sitiados também construíram máquinas contra as máquinas deles e resistiram durante muitos dias."},
{v:53,t:"Mas não havia víveres nos depósitos, porque era o sétimo ano, e os que tinham fugido das nações para a Judeia tinham consumido o resto das provisões."},
{v:54,t:"Ficaram poucos homens no santuário, porque a fome os dominava; os outros se dispersaram, cada um para a sua casa."},
{s:"Lísias faz a paz com os judeus"},
{v:55,t:"Lísias soube então que Filipe, a quem o rei Antíoco, ainda em vida, encarregara de educar o seu filho Antíoco para reinar,"},
{v:56,t:"tinha voltado da Pérsia e da Média com as tropas que tinham ido com o rei, e que procurava assumir o governo."},
{v:57,t:"Apressou-se então a dar o sinal de partida e disse ao rei, aos comandantes do exército e aos soldados: Enfraquecemos a cada dia, os víveres são escassos, o lugar que sitiamos é bem fortificado, e os negócios do reino nos pressionam."},
{v:58,t:"Estendamos, pois, a mão direita a esses homens; façamos a paz com eles e com todo o seu povo,"},
{v:59,t:"e permitamos que vivam segundo as suas leis, como antes; pois foi por causa das suas leis, que nós abolimos, que eles se irritaram e fizeram tudo isso."},
{v:60,t:"A proposta agradou ao rei e aos chefes; mandou propor-lhes a paz, e eles a aceitaram."},
{v:61,t:"O rei e os chefes lhes fizeram um juramento, e com essas garantias eles saíram da fortaleza."},
{v:62,t:"Mas, quando o rei entrou no monte Sião e viu como o lugar era fortificado, violou o juramento que tinha feito e mandou demolir a muralha ao redor."},
{v:63,t:"Depois partiu às pressas e voltou para Antioquia, onde encontrou Filipe senhor da cidade; combateu contra ele e tomou a cidade à força."}
];

window.TEXTOS_SEED["1macabeus"][7] = [
{s:"Demétrio I e o sumo sacerdote Alcimo"},
{v:1,t:"No ano cento e cinquenta e um, Demétrio, filho de Seleuco, saiu de Roma e desembarcou com poucos homens numa cidade do litoral, onde se proclamou rei.",n:"Ano cento e cinquenta e um: 162–161 a.C. Demétrio I, sobrinho de Antíoco Epífanes, vivia em Roma como refém e fugiu de lá."},
{v:2,t:"Quando ele entrava no palácio real dos seus pais, o exército prendeu Antíoco e Lísias para entregá-los a ele."},
{v:3,t:"Ao saber disso, ele disse: Não quero ver a cara deles."},
{v:4,t:"Os soldados os mataram, e Demétrio sentou-se no trono do seu reino."},
{v:5,t:"Foram ter com ele todos os homens sem lei e ímpios de Israel, conduzidos por Alcimo, que ambicionava o sumo sacerdócio."},
{v:6,t:"Acusaram o povo diante do rei, dizendo: Judas e os seus irmãos mataram todos os teus amigos e nos expulsaram da nossa terra."},
{v:7,t:"Envia, pois, agora um homem de tua confiança, que vá ver toda a devastação que ele fez a nós e à província do rei, e castigue a eles e a todos os que os ajudam."},
{v:8,t:"O rei escolheu Báquides, um dos amigos do rei, governador da Transeufratênia, grande no reino e fiel ao rei, e o enviou,",np:1},
{v:9,t:"com o ímpio Alcimo, a quem confirmou no sacerdócio, e ordenou-lhe que se vingasse dos filhos de Israel."},
{v:10,t:"Partiram e chegaram à terra de Judá com um grande exército; e Báquides enviou a Judas e aos seus irmãos mensageiros com palavras de paz, mas com astúcia."},
{v:11,t:"Eles não deram atenção às suas palavras, porque viram que tinham vindo com um grande exército."},
{v:12,t:"Todavia, um grupo de escribas foi ter com Alcimo e Báquides, em busca de um acordo justo;"},
{v:13,t:"e os assideus eram os primeiros entre os filhos de Israel a pedir-lhes a paz."},
{v:14,t:"Diziam: Um sacerdote da descendência de Aarão veio com estas tropas; ele não nos fará mal."},
{v:15,t:"Alcimo falou-lhes com palavras de paz e lhes jurou: Não procuraremos fazer mal a vós nem aos vossos amigos.",np:1},
{v:16,t:"Eles acreditaram nele; mas ele prendeu sessenta deles e os matou num só dia, segundo a palavra da Escritura:"},
{v:17,t:"Espalharam a carne dos teus fiéis e derramaram o seu sangue ao redor de Jerusalém, e não havia quem os sepultasse.",np:1,n:"Citação livre do Salmo 79,2–3."},
{v:18,t:"O medo e o terror caíram sobre todo o povo, que dizia: Não há neles verdade nem justiça, pois violaram o acordo e o juramento que fizeram.",np:1},
{v:19,t:"Báquides partiu de Jerusalém e acampou em Bet-Zait; mandou prender muitos dos que tinham desertado para o seu lado e alguns do povo, matou-os e os jogou no grande poço."},
{v:20,t:"Confiou a região a Alcimo e deixou com ele tropas para ajudá-lo; depois Báquides voltou para junto do rei."},
{v:21,t:"Alcimo lutava para se manter no sumo sacerdócio.",np:1},
{v:22,t:"Juntaram-se a ele todos os que perturbavam o seu povo; apoderaram-se da terra de Judá e causaram grandes males a Israel."},
{v:23,t:"Judas viu todo o mal que Alcimo e os seus partidários faziam aos filhos de Israel, pior do que o dos pagãos;"},
{v:24,t:"e percorreu todo o território da Judeia, castigando os desertores, de modo que eles deixaram de circular pela região."},
{v:25,t:"Quando Alcimo viu que Judas e os seus companheiros se tinham fortalecido e percebeu que não podia resistir-lhes, voltou para junto do rei e os acusou de crimes graves."},
{s:"Nicanor contra Judas"},
{v:26,t:"Então o rei enviou Nicanor, um dos seus generais mais ilustres, que odiava Israel e lhe era hostil, e ordenou-lhe que exterminasse o povo."},
{v:27,t:"Nicanor chegou a Jerusalém com um grande exército e mandou a Judas e aos seus irmãos, com astúcia, esta mensagem de paz:"},
{v:28,t:"Que não haja combate entre mim e vós; irei com poucos homens, para vos ver em paz."},
{v:29,t:"Foi ter com Judas, e saudaram-se amigavelmente; mas os inimigos estavam prontos para raptar Judas."},
{v:30,t:"Judas soube que ele tinha vindo com astúcia e ficou com medo dele; e não quis mais vê-lo."},
{v:31,t:"Nicanor percebeu que o seu plano tinha sido descoberto e saiu para combater Judas perto de Cafarsalama."},
{v:32,t:"Caíram do exército de Nicanor uns quinhentos homens, e os outros fugiram para a Cidade de Davi."},
{v:33,t:"Depois disso, Nicanor subiu ao monte Sião. Alguns sacerdotes saíram do santuário, com alguns anciãos do povo, para saudá-lo amigavelmente e mostrar-lhe o holocausto que se oferecia pelo rei."},
{v:34,t:"Mas ele zombou deles, ridicularizou-os, contaminou-os e falou com arrogância;"},
{v:35,t:"e jurou com furor: Se Judas e o seu exército não me forem entregues agora mesmo, quando eu voltar vitorioso, incendiarei este templo. E saiu furioso."},
{v:36,t:"Os sacerdotes entraram, puseram-se diante do altar e do santuário e, chorando, disseram:"},
{v:37,t:"Tu escolheste esta casa para que nela fosse invocado o teu nome, para que fosse casa de oração e de súplica para o teu povo.",np:1},
{v:38,t:"Vinga-te deste homem e do seu exército, e que caiam pela espada; lembra-te das suas blasfêmias e não lhes dês trégua."},
{s:"A vitória de Adasa"},
{v:39,t:"Nicanor saiu de Jerusalém e acampou em Bet-Horon, onde se juntou a ele um exército da Síria."},
{v:40,t:"Judas acampou em Adasa com três mil homens, e rezou assim:"},
{v:41,t:"Quando os enviados do rei blasfemaram, o teu anjo saiu e matou cento e oitenta e cinco mil deles.",n:"Alusão aos enviados de Senaquerib, rei da Assíria (2 Reis 18,17–19,35)."},
{v:42,t:"Esmaga hoje, do mesmo modo, este exército diante de nós, e que os outros saibam que ele falou mal do teu santuário; julga-o segundo a sua maldade."},
{v:43,t:"Os exércitos travaram combate no dia treze do mês de Adar; o exército de Nicanor foi esmagado, e ele foi o primeiro a cair na batalha."},
{v:44,t:"Quando os seus soldados viram que Nicanor tinha caído, largaram as armas e fugiram."},
{v:45,t:"Os judeus os perseguiram durante um dia de caminho, desde Adasa até perto de Gazer, tocando atrás deles as trombetas de sinal."},
{v:46,t:"De todas as aldeias da Judeia ao redor saíram homens que os cercaram e os fizeram voltar contra os perseguidores; e todos caíram pela espada: não sobrou nenhum."},
{v:47,t:"Tomaram os despojos e o saque; cortaram a cabeça de Nicanor e a mão direita que ele estendera com arrogância, e levaram-nas para expô-las diante de Jerusalém."},
{v:48,t:"O povo encheu-se de alegria e celebrou aquele dia como um grande dia de festa;",np:1},
{v:49,t:"e determinaram que esse dia fosse celebrado todos os anos, no dia treze de Adar.",n:"É o dia de Nicanor, véspera da festa de Purim (Ester 9,17)."},
{v:50,t:"E a terra de Judá teve tranquilidade por algum tempo."}
];

window.TEXTOS_SEED["1macabeus"][8] = [
{s:"A fama dos romanos"},
{v:1,t:"Judas ouviu falar da fama dos romanos: que tratavam com benevolência todos os que se aliavam a eles e faziam amizade com todos os que os procuravam,"},
{v:2,t:"e que eram muito poderosos. Contaram-lhe as suas guerras e as façanhas que tinham realizado entre os gálatas, como os tinham dominado e submetido a tributo;",n:"Gálatas: talvez os gauleses do norte da Itália, vencidos por Roma no começo do século II a.C., ou os gálatas da Ásia Menor, derrotados em 189 a.C."},
{v:3,t:"o que tinham feito na Espanha para se apoderarem das minas de prata e de ouro que ali há;"},
{v:4,t:"como, com a sua prudência e perseverança, tinham conquistado toda aquela terra, embora ficasse muito longe deles; como tinham vencido os reis que vieram contra eles desde os confins da terra, esmagando-os e infligindo-lhes grandes derrotas, enquanto os outros lhes pagam tributo todos os anos;"},
{v:5,t:"como tinham derrotado na guerra e submetido Filipe e Perseu, reis de Cetim, e os que se tinham levantado contra eles;",n:"Filipe V e o seu filho Perseu, reis da Macedônia, vencidos pelos romanos em 197 e em 168 a.C."},
{v:6,t:"como Antíoco, o grande rei da Ásia, que lhes movera guerra com cento e vinte elefantes, cavalaria, carros e um exército muito numeroso, fora esmagado por eles;",n:"Antíoco III, o Grande, vencido pelos romanos em Magnésia, em 190 a.C."},
{v:7,t:"como o tinham capturado vivo e lhe tinham imposto, a ele e aos seus sucessores, um pesado tributo, a entrega de reféns e a cessão",n:"Na realidade, Antíoco III não foi capturado; mas a paz de Apameia (188 a.C.) impôs-lhe um tributo enorme e a entrega de reféns, entre os quais o seu filho, o futuro Antíoco Epífanes."},
{v:8,t:"da Índia, da Média e da Lídia, das suas melhores províncias, que tomaram dele e deram ao rei Eumenes;",n:"Índia e Média: talvez erro de cópia por Iônia e Mísia, províncias da Ásia Menor dadas a Eumenes II, rei de Pérgamo."},
{v:9,t:"como os da Grécia planejaram atacá-los e destruí-los, e os romanos o souberam;"},
{v:10,t:"enviaram contra eles um só general e os combateram; muitos deles caíram mortos, levaram cativas as suas mulheres e os seus filhos, saquearam-nos, apoderaram-se da sua terra, derrubaram as suas fortalezas e os reduziram à escravidão até o dia de hoje;",n:"Alusão à guerra contra a Liga Aqueia, que terminou com a destruição de Corinto em 146 a.C., depois da morte de Judas."},
{v:11,t:"como aniquilaram e submeteram os outros reinos e as ilhas que alguma vez lhes resistiram;"},
{v:12,t:"mas com os seus amigos e com os que confiavam neles mantiveram a amizade. Dominaram reinos próximos e distantes, e todos os que ouviam o seu nome os temiam."},
{v:13,t:"Aqueles a quem querem ajudar a reinar, reinam; e depõem os que querem. Assim se elevaram muito alto."},
{v:14,t:"E, apesar de tudo isso, nenhum deles pôs o diadema nem se vestiu de púrpura para se engrandecer."},
{v:15,t:"Criaram um senado, onde trezentos e vinte conselheiros deliberam todos os dias, cuidando sempre do povo, para que seja bem governado.",n:"O senado romano tinha trezentos membros e não se reunia todos os dias; o autor descreve Roma de longe, com admiração."},
{v:16,t:"Todos os anos confiam a um só homem o governo e o domínio de toda a sua terra; todos obedecem a esse único, e não há entre eles inveja nem rivalidade.",n:"Na realidade, Roma elegia dois cônsules por ano."},
{s:"A aliança com Roma"},
{v:17,t:"Judas escolheu Eupólemo, filho de João, filho de Acos, e Jasão, filho de Eleazar, e enviou-os a Roma para estabelecerem amizade e aliança com eles,"},
{v:18,t:"e para que os livrassem do jugo, pois viam que o reino dos gregos reduzia Israel à escravidão."},
{v:19,t:"Foram a Roma, depois de uma viagem muito longa, entraram no senado e tomaram a palavra:"},
{v:20,t:"Judas, chamado Macabeu, os seus irmãos e o povo dos judeus nos enviaram a vós para estabelecer convosco aliança e paz, e para sermos inscritos entre os vossos aliados e amigos."},
{v:21,t:"A proposta lhes agradou."},
{v:22,t:"Esta é a cópia da carta que responderam, gravada em placas de bronze e enviada a Jerusalém, para que ficasse lá como memorial da paz e da aliança:"},
{v:23,t:"Prosperidade aos romanos e à nação dos judeus, no mar e na terra, para sempre; e que a espada e o inimigo estejam longe deles."},
{v:24,t:"Se Roma, primeiro, ou algum dos seus aliados, em qualquer parte do seu domínio, sofrer uma guerra,"},
{v:25,t:"a nação dos judeus lutará ao seu lado de todo o coração, conforme as circunstâncias o exigirem;"},
{v:26,t:"e não darão nem fornecerão aos inimigos trigo, armas, dinheiro ou navios, conforme decidiu Roma; e cumprirão os seus compromissos sem receber nada em troca."},
{v:27,t:"Do mesmo modo, se a nação dos judeus sofrer primeiro uma guerra, os romanos lutarão ao seu lado de boa vontade, conforme as circunstâncias o permitirem;"},
{v:28,t:"e aos inimigos não se darão trigo, armas, dinheiro ou navios, conforme decidiu Roma; e cumprirão esses compromissos sem fraude."},
{v:29,t:"Nesses termos os romanos fizeram o tratado com o povo dos judeus."},
{v:30,t:"Se, depois disso, uma ou outra parte quiser acrescentar ou suprimir alguma cláusula, poderá fazê-lo de comum acordo, e o que for acrescentado ou suprimido terá valor."},
{v:31,t:"Quanto aos males que o rei Demétrio lhes está causando, nós lhe escrevemos, dizendo: Por que fizeste pesar o teu jugo sobre os nossos amigos e aliados judeus?"},
{v:32,t:"Se eles voltarem a queixar-se de ti, nós lhes faremos justiça e te faremos guerra por mar e por terra."}
];

window.TEXTOS_SEED["1macabeus"][9] = [
{s:"A morte de Judas"},
{v:1,t:"Quando Demétrio soube que Nicanor e o seu exército tinham caído em combate, enviou de novo Báquides e Alcimo à terra de Judá, e com eles a ala direita do seu exército."},
{v:2,t:"Tomaram o caminho de Guilgal e acamparam diante de Masalot, em Arbela; tomaram-na e mataram muita gente."},
{v:3,t:"No primeiro mês do ano cento e cinquenta e dois, acamparam diante de Jerusalém;",n:"Ano cento e cinquenta e dois: primavera de 160 a.C."},
{v:4,t:"depois partiram e foram para Beret, com vinte mil homens e dois mil cavaleiros."},
{v:5,t:"Judas estava acampado em Elasa, com três mil homens escolhidos."},
{v:6,t:"Quando viram o tamanho daquele exército, ficaram com muito medo, e muitos desertaram do acampamento; não ficaram senão oitocentos homens."},
{v:7,t:"Judas viu que o seu exército se desfazia e que a batalha o apertava; ficou com o coração partido, porque não tinha tempo de reunir os seus,"},
{v:8,t:"e desanimou. Mas disse aos que tinham ficado: Levantemo-nos e subamos contra os nossos adversários; talvez possamos combatê-los."},
{v:9,t:"Eles procuravam dissuadi-lo, dizendo: Não conseguiremos. Salvemos agora a nossa vida; depois voltaremos com os nossos irmãos e os combateremos. Somos muito poucos."},
{v:10,t:"Judas respondeu: Longe de mim fazer uma coisa dessas, fugir diante deles! Se chegou a nossa hora, morramos com valentia pelos nossos irmãos, e não deixemos mancha na nossa glória."},
{v:11,t:"O exército inimigo saiu do acampamento e pôs-se em posição diante deles; a cavalaria dividiu-se em duas alas, os fundibulários e os arqueiros iam à frente do exército, e na primeira linha estavam todos os mais valentes."},
{v:12,t:"Báquides estava na ala direita. A falange avançou pelos dois lados, ao som das trombetas; os homens de Judas também tocaram as trombetas,"},
{v:13,t:"e a terra tremeu com o estrondo dos exércitos. O combate durou da manhã até a tarde."},
{v:14,t:"Judas viu que Báquides e o grosso do exército estavam à direita; reuniram-se com ele todos os mais corajosos,",np:1},
{v:15,t:"e a ala direita foi esmagada por eles; e Judas perseguiu-os até o monte Azoto.",n:"Monte Azoto: lugar desconhecido; talvez se deva ler Hasor, ao norte de Jerusalém."},
{v:16,t:"Os da ala esquerda viram que a ala direita tinha sido esmagada e voltaram-se contra Judas e os seus homens, atacando-os pelas costas."},
{v:17,t:"O combate tornou-se encarniçado, e muitos caíram mortos de um lado e de outro."},
{v:18,t:"Judas também caiu, e os outros fugiram.",n:"Judas morreu em 160 a.C."},
{v:19,t:"Jônatas e Simão levaram o corpo do seu irmão Judas e o sepultaram no túmulo dos seus pais, em Modin."},
{v:20,t:"Todo o Israel o chorou e fez por ele um grande luto; durante muitos dias o lamentaram,"},
{v:21,t:"dizendo: Como caiu o herói, o salvador de Israel!",n:"Eco do lamento de Davi por Saul e Jônatas (2 Samuel 1,19.25.27)."},
{v:22,t:"O resto dos feitos de Judas, das suas guerras, das façanhas que realizou e da sua grandeza não foi escrito, porque era demais.",np:1},
{s:"Jônatas sucede a Judas"},
{v:23,t:"Depois da morte de Judas, os homens sem lei reapareceram em todo o território de Israel, e surgiram todos os que praticavam a injustiça."},
{v:24,t:"Naqueles dias houve uma fome muito grande, e a região passou para o lado deles."},
{v:25,t:"Báquides escolheu homens ímpios e os fez senhores da região."},
{v:26,t:"Eles procuravam e rastreavam os amigos de Judas e os levavam a Báquides, que se vingava deles e os escarnecia."},
{v:27,t:"Houve em Israel uma grande tribulação, como não houvera desde o dia em que deixaram de aparecer profetas entre eles."},
{v:28,t:"Então todos os amigos de Judas se reuniram e disseram a Jônatas:",np:1},
{v:29,t:"Desde que o teu irmão Judas morreu, não há homem como ele para sair contra os inimigos, contra Báquides e contra os que odeiam a nossa nação."},
{v:30,t:"Por isso, hoje te escolhemos para seres, em lugar dele, o nosso chefe e comandante nas nossas batalhas."},
{v:31,t:"Naquele momento, Jônatas assumiu o comando e ocupou o lugar do seu irmão Judas."},
{s:"Jônatas no deserto de Técua"},
{v:32,t:"Quando Báquides soube disso, procurou matá-lo."},
{v:33,t:"Jônatas, o seu irmão Simão e todos os que estavam com ele souberam disso; fugiram para o deserto de Técua e acamparam junto às águas do poço de Asfar."},
{v:34,t:"Báquides soube disso num dia de sábado e foi com todo o seu exército para o outro lado do Jordão.",n:"Este versículo parece antecipar o 43."},
{v:35,t:"Jônatas enviou o seu irmão João, que conduzia o povo, a pedir aos seus amigos nabateus que guardassem as muitas bagagens que tinham."},
{v:36,t:"Mas os filhos de Jambri, de Medaba, saíram, prenderam João com tudo o que ele levava e foram-se embora com tudo."},
{v:37,t:"Depois disso, contaram a Jônatas e ao seu irmão Simão que os filhos de Jambri celebravam um grande casamento e traziam de Nadabat, com um grande cortejo, a noiva, filha de um dos grandes chefes de Canaã."},
{v:38,t:"Lembraram-se do sangue do seu irmão João; subiram e esconderam-se ao abrigo da montanha."},
{v:39,t:"Levantaram os olhos e viram um cortejo ruidoso, com muita bagagem; o noivo, com os seus amigos e irmãos, saiu ao encontro dele, com tamborins, músicos e muitas armas."},
{v:40,t:"Então saíram da emboscada contra eles e os mataram; muitos caíram mortos, e os restantes fugiram para a montanha. E tomaram todos os seus despojos."},
{v:41,t:"Assim o casamento se transformou em luto, e o som das suas músicas em lamento."},
{v:42,t:"Tendo vingado o sangue do seu irmão, voltaram para os pântanos do Jordão."},
{s:"A batalha do Jordão"},
{v:43,t:"Báquides soube disso e veio num dia de sábado, com um grande exército, até as margens do Jordão."},
{v:44,t:"Jônatas disse aos seus: Levantemo-nos e combatamos pela nossa vida, porque hoje não é como antes:"},
{v:45,t:"temos a batalha pela frente, e de um lado e de outro as águas do Jordão, os pântanos e o mato; não há por onde escapar."},
{v:46,t:"Clamai, pois, agora ao Céu, para serdes salvos das mãos dos vossos inimigos. E começou o combate."},
{v:47,t:"Jônatas estendeu a mão para ferir Báquides, mas este recuou e escapou."},
{v:48,t:"Então Jônatas e os seus homens se lançaram no Jordão e atravessaram a nado para a outra margem; e os inimigos não atravessaram o Jordão atrás deles.",np:1},
{v:49,t:"Naquele dia caíram do lado de Báquides uns mil homens. E voltaram para Jerusalém."},
{v:50,t:"Fortificaram cidades na Judeia: a fortaleza de Jericó, Emaús, Bet-Horon, Betel, Tamnata, Faraton e Tefon, com muralhas altas, portas e ferrolhos;"},
{v:51,t:"e Báquides pôs guarnições nelas para hostilizar Israel."},
{v:52,t:"Fortificou também a cidade de Bet-Sur, Gazer e a Cidadela, e pôs nelas tropas e depósitos de víveres."},
{v:53,t:"Tomou como reféns os filhos dos chefes da região e os pôs sob guarda na Cidadela de Jerusalém."},
{s:"A morte de Alcimo"},
{v:54,t:"No segundo mês do ano cento e cinquenta e três, Alcimo mandou demolir o muro do pátio interior do santuário, destruindo assim a obra dos profetas. E começou a demolição.",n:"Ano cento e cinquenta e três: 159 a.C. O muro separava o pátio reservado a Israel do pátio dos pagãos; a obra dos profetas é o templo reconstruído no tempo de Ageu e Zacarias."},
{v:55,t:"Mas naquele momento Alcimo foi ferido por um ataque, e as obras foram interrompidas; a sua boca ficou travada, ele ficou paralisado e não podia mais dizer palavra nem dar instruções sobre a sua casa."},
{v:56,t:"E Alcimo morreu naquele tempo, com grandes sofrimentos."},
{v:57,t:"Vendo que Alcimo tinha morrido, Báquides voltou para junto do rei; e a terra de Judá ficou em paz durante dois anos."},
{s:"O cerco de Bet-Basi e a paz com Báquides"},
{v:58,t:"Então todos os homens sem lei tramaram, dizendo: Jônatas e os seus vivem tranquilos e confiantes; tragamos agora Báquides, e ele os prenderá todos numa só noite."},
{v:59,t:"Foram ter com ele e lhe deram esse conselho."},
{v:60,t:"Báquides pôs-se a caminho com um grande exército e enviou cartas secretas a todos os seus aliados na Judeia, para que prendessem Jônatas e os seus companheiros; mas não conseguiram, porque o plano foi descoberto."},
{v:61,t:"Jônatas e os seus prenderam uns cinquenta homens da região, cabeças daquela maldade, e os mataram."},
{v:62,t:"Depois Jônatas, Simão e os seus homens retiraram-se para Bet-Basi, no deserto; reconstruíram o que estava em ruínas e a fortificaram."},
{v:63,t:"Báquides soube disso, reuniu toda a sua gente e convocou também os seus partidários da Judeia."},
{v:64,t:"Veio e acampou diante de Bet-Basi; atacou-a durante muitos dias e construiu máquinas de guerra."},
{v:65,t:"Jônatas deixou o seu irmão Simão na cidade e saiu pela região com um pequeno grupo de homens;"},
{v:66,t:"derrotou Odomera e os seus irmãos, e os filhos de Fasiron nas suas tendas; e começou a atacar e a crescer em forças."},
{v:67,t:"Simão e os seus homens saíram da cidade e incendiaram as máquinas de guerra;"},
{v:68,t:"combateram contra Báquides e o derrotaram; afligiram-no muito, porque o seu plano e a sua expedição tinham fracassado."},
{v:69,t:"Ele se enfureceu contra os homens sem lei que o tinham aconselhado a vir à região, matou muitos deles e decidiu voltar para a sua terra."},
{v:70,t:"Jônatas soube disso e enviou-lhe embaixadores para fazer a paz com ele e obter a devolução dos prisioneiros."},
{v:71,t:"Báquides aceitou, fez o que ele propunha e jurou-lhe não procurar fazer-lhe mal enquanto vivesse."},
{v:72,t:"Devolveu-lhe os prisioneiros que antes tinha capturado na terra de Judá; depois voltou para a sua terra e não tornou mais a vir ao território deles."},
{v:73,t:"Assim cessou a espada em Israel. Jônatas foi morar em Micmás; começou a governar o povo e fez desaparecer de Israel os ímpios."}
];

window.TEXTOS_SEED["1macabeus"][10] = [
{s:"Demétrio procura a amizade de Jônatas"},
{v:1,t:"No ano cento e sessenta, Alexandre Epífanes, filho de Antíoco, desembarcou e ocupou Ptolemaida; foi bem recebido e começou a reinar ali.",n:"Ano cento e sessenta: 152 a.C. Alexandre Balas se apresentava como filho de Antíoco Epífanes e tinha o apoio de Roma."},
{v:2,t:"Quando o rei Demétrio soube disso, reuniu um exército muito numeroso e saiu para combatê-lo."},
{v:3,t:"Demétrio enviou a Jônatas uma carta com palavras de paz, para engrandecê-lo;"},
{v:4,t:"pois dizia: Antecipemo-nos a fazer a paz com ele, antes que ele a faça com Alexandre contra nós;"},
{v:5,t:"porque ele se lembrará de todos os males que causamos a ele, aos seus irmãos e à sua nação."},
{v:6,t:"Deu-lhe autorização para reunir tropas, fabricar armas e ser seu aliado, e mandou que lhe entregassem os reféns que estavam na Cidadela."},
{v:7,t:"Jônatas foi a Jerusalém e leu a carta diante de todo o povo e dos que estavam na Cidadela."},
{v:8,t:"Estes ficaram com muito medo quando ouviram que o rei lhe dera autorização para reunir tropas."},
{v:9,t:"Os da Cidadela entregaram os reféns a Jônatas, e ele os devolveu aos seus pais."},
{v:10,t:"Jônatas estabeleceu-se em Jerusalém e começou a reconstruir e restaurar a cidade."},
{v:11,t:"Mandou aos operários que reconstruíssem as muralhas e cercassem o monte Sião com pedras de cantaria, para fortificá-lo; e assim fizeram."},
{v:12,t:"Os estrangeiros que estavam nas fortalezas construídas por Báquides fugiram;"},
{v:13,t:"cada um abandonou o seu posto e voltou para a sua terra."},
{v:14,t:"Só em Bet-Sur ficaram alguns dos que tinham abandonado a Lei e os mandamentos, porque era para eles um refúgio."},
{s:"Jônatas, sumo sacerdote"},
{v:15,t:"O rei Alexandre soube das promessas que Demétrio fizera a Jônatas; contaram-lhe também as guerras e as façanhas dele e dos seus irmãos, e as fadigas que tinham suportado."},
{v:16,t:"E disse: Acharemos outro homem como este? Façamos dele agora o nosso amigo e aliado."},
{v:17,t:"Escreveu-lhe então uma carta nestes termos:"},
{v:18,t:"O rei Alexandre saúda o seu irmão Jônatas."},
{v:19,t:"Ouvimos dizer de ti que és homem valente e poderoso e digno de ser nosso amigo.",np:1},
{v:20,t:"Por isso, hoje te nomeamos sumo sacerdote da tua nação e te conferimos o título de amigo do rei — e enviou-lhe um manto de púrpura e uma coroa de ouro —; toma o nosso partido e conserva a amizade conosco."},
{v:21,t:"Jônatas vestiu os paramentos sagrados no sétimo mês do ano cento e sessenta, na festa das Tendas; reuniu tropas e fabricou muitas armas.",n:"Outubro de 152 a.C. Desde a morte de Alcimo (9,56), o cargo estava vago; Jônatas, que não era da família dos sumos sacerdotes anteriores, o recebe das mãos de um rei pagão."},
{s:"As promessas de Demétrio"},
{v:22,t:"Quando Demétrio soube disso, ficou muito aborrecido e disse:"},
{v:23,t:"Que fizemos, para que Alexandre se antecipasse a nós em conquistar a amizade dos judeus e reforçar-se com eles?"},
{v:24,t:"Também eu lhes escreverei palavras de encorajamento, oferecendo-lhes honras e presentes, para que estejam do meu lado."},
{v:25,t:"E escreveu-lhes nestes termos: O rei Demétrio saúda a nação dos judeus."},
{v:26,t:"Soubemos com alegria que guardastes os tratados conosco, permanecestes na nossa amizade e não passastes para o lado dos nossos inimigos."},
{v:27,t:"Continuai, pois, a guardar a vossa fidelidade para conosco, e vos retribuiremos com benefícios o que fizerdes por nós:"},
{v:28,t:"vos concederemos muitas isenções e vos daremos presentes."},
{v:29,t:"Desde já libero e isento todos os judeus dos tributos, do imposto sobre o sal e das coroas;",n:"Coroas: contribuição em ouro, oferecida de início como presente ao rei e depois transformada em imposto."},
{v:30,t:"e renuncio, de hoje em diante, a cobrar a terça parte das sementeiras e a metade dos frutos das árvores que me cabem, na terra de Judá e nos três distritos anexados a ela, da Samaria e da Galileia, a partir de hoje e para sempre."},
{v:31,t:"Jerusalém e o seu território sejam santos e isentos, com os dízimos e as taxas."},
{v:32,t:"Renuncio também ao controle da Cidadela de Jerusalém e o entrego ao sumo sacerdote, para que ponha nela, como guarnição, os homens que ele mesmo escolher.",np:1},
{v:33,t:"Todo judeu levado cativo da terra de Judá para qualquer parte do meu reino, eu o ponho em liberdade sem resgate; e todos fiquem isentos de impostos, até sobre o gado."},
{v:34,t:"Todas as festas, os sábados, as luas novas, os dias estabelecidos, os três dias antes e os três dias depois de cada festa sejam dias de isenção e de dispensa para todos os judeus que estão no meu reino;"},
{v:35,t:"e ninguém terá autoridade para cobrar deles qualquer coisa ou importunar qualquer um deles por qualquer motivo."},
{v:36,t:"Sejam alistados nas tropas do rei até trinta mil judeus, e se lhes pagará o soldo como a todas as tropas do rei.",np:1},
{v:37,t:"Alguns deles serão postos nas grandes fortalezas do rei, e outros nos cargos de confiança do reino; os seus superiores e comandantes serão também judeus, e viverão segundo as suas leis, como o rei ordenou para a terra de Judá."},
{v:38,t:"Os três distritos da região da Samaria anexados à Judeia sejam considerados parte da Judeia, de modo que estejam sob um só chefe e não obedeçam a outra autoridade senão à do sumo sacerdote."},
{v:39,t:"Dou Ptolemaida e o seu território, como presente, ao santuário de Jerusalém, para as despesas necessárias do culto."},
{v:40,t:"Além disso, darei todos os anos quinze mil siclos de prata, da receita real proveniente dos lugares que me pertencem."},
{v:41,t:"E todo o atraso que os funcionários não pagaram, como faziam nos anos anteriores, será entregue de agora em diante para as obras do templo."},
{v:42,t:"Além disso, dos cinco mil siclos de prata que se cobravam todos os anos da receita do santuário, também deles faço remissão, porque pertencem aos sacerdotes que oficiam no culto."},
{v:43,t:"Todos os que se refugiarem no templo de Jerusalém ou em qualquer parte do seu recinto, por dívidas para com o rei ou por qualquer outra, fiquem livres, com todos os bens que tiverem no meu reino."},
{v:44,t:"As despesas para construir e restaurar as obras do santuário serão pagas pela receita real;"},
{v:45,t:"e também as despesas para reconstruir as muralhas de Jerusalém e fortificá-la ao redor, e para reconstruir as muralhas das cidades da Judeia, serão pagas pela receita real."},
{v:46,t:"Quando Jônatas e o povo ouviram essas palavras, não acreditaram nelas nem as aceitaram, porque se lembravam do grande mal que ele fizera a Israel e de como os tinha oprimido.",np:1},
{v:47,t:"Preferiram Alexandre, porque ele fora o primeiro a lhes propor a paz, e foram sempre seus aliados."},
{s:"A morte de Demétrio"},
{v:48,t:"O rei Alexandre reuniu um grande exército e acampou diante de Demétrio."},
{v:49,t:"Os dois reis travaram combate; o exército de Alexandre fugiu, e Demétrio o perseguiu e levou vantagem sobre eles.",n:"Assim a Nova Vulgata, com parte dos manuscritos gregos; outros dizem o contrário: o exército de Demétrio fugiu, e Alexandre o perseguiu. De qualquer modo, a batalha terminou com a morte de Demétrio."},
{v:50,t:"O combate foi muito duro até o pôr do sol, e naquele dia Demétrio caiu.",n:"Em 150 a.C."},
{s:"Alexandre casa-se com Cleópatra"},
{v:51,t:"Alexandre enviou embaixadores a Ptolomeu, rei do Egito, com esta mensagem:"},
{v:52,t:"Voltei à terra do meu reino, sentei-me no trono dos meus pais e assumi o poder; esmaguei Demétrio e apoderei-me do nosso país;"},
{v:53,t:"travei combate com ele, e ele e o seu exército foram esmagados por nós, e sentamo-nos no trono do seu reino."},
{v:54,t:"Façamos agora amizade um com o outro: dá-me a tua filha por esposa, e eu serei teu genro e darei a ti e a ela presentes dignos de ti."},
{v:55,t:"O rei Ptolomeu respondeu: Feliz o dia em que voltaste à terra dos teus pais e te sentaste no trono do seu reino!"},
{v:56,t:"Farei por ti o que escreveste; mas vem ao meu encontro em Ptolemaida, para que nos vejamos, e eu serei teu sogro, como disseste."},
{v:57,t:"Ptolomeu saiu do Egito com a sua filha Cleópatra e chegou a Ptolemaida no ano cento e sessenta e dois.",n:"Em 150 a.C."},
{v:58,t:"O rei Alexandre foi ao seu encontro; Ptolomeu deu-lhe a sua filha Cleópatra e celebrou o casamento em Ptolemaida, com grande magnificência, como costumam os reis."},
{s:"Jônatas honrado em Ptolemaida"},
{v:59,t:"O rei Alexandre escreveu a Jônatas que viesse ao seu encontro."},
{v:60,t:"Jônatas foi com pompa a Ptolemaida, encontrou-se com os dois reis e deu-lhes prata, ouro e muitos presentes, a eles e aos seus amigos; e caiu nas suas graças."},
{v:61,t:"Juntaram-se contra ele alguns homens perversos de Israel, homens sem lei, para acusá-lo; mas o rei não lhes deu atenção."},
{v:62,t:"O rei mandou que tirassem as vestes de Jônatas e o vestissem de púrpura; e assim fizeram. E o rei o fez sentar-se ao seu lado."},
{v:63,t:"Depois disse aos seus oficiais: Saí com ele pelo meio da cidade e proclamai que ninguém o acuse de coisa alguma, nem o importune por nenhum motivo."},
{v:64,t:"Quando os seus acusadores viram as honras que lhe eram proclamadas e o viram vestido de púrpura, fugiram todos."},
{v:65,t:"O rei o honrou, inscreveu-o entre os seus primeiros amigos e o nomeou general e governador da província."},
{v:66,t:"E Jônatas voltou para Jerusalém em paz e com alegria."},
{s:"A vitória de Jônatas sobre Apolônio"},
{v:67,t:"No ano cento e sessenta e cinco, Demétrio, filho de Demétrio, veio de Creta para a terra dos seus pais.",n:"Em 147 a.C. É Demétrio II."},
{v:68,t:"Quando o rei Alexandre soube disso, ficou muito aborrecido e voltou para Antioquia."},
{v:69,t:"Demétrio nomeou Apolônio, governador da Celessíria, que reuniu um grande exército, acampou diante de Jâmnia e mandou dizer ao sumo sacerdote Jônatas:"},
{v:70,t:"Só tu te levantas contra nós, e por tua causa me tornei objeto de riso e de vergonha. Por que te fazes forte contra nós nas montanhas?"},
{v:71,t:"Se confias nas tuas forças, desce até nós na planície, e mediremos ali as nossas forças, porque comigo estão as tropas das cidades."},
{v:72,t:"Pergunta e fica sabendo quem sou eu e quem são os outros que nos ajudam. Eles dizem: Não podereis manter-vos de pé diante de nós, porque os teus pais foram derrotados duas vezes na sua própria terra."},
{v:73,t:"Não poderás resistir a tal cavalaria e a tal exército na planície, onde não há pedra, nem seixo, nem lugar para fugir."},
{v:74,t:"Quando Jônatas ouviu as palavras de Apolônio, ficou indignado; escolheu dez mil homens e saiu de Jerusalém, e o seu irmão Simão veio ao seu encontro para ajudá-lo.",np:1},
{v:75,t:"Acampou diante de Jope; mas os habitantes lhe fecharam as portas, porque havia em Jope uma guarnição de Apolônio. Então a atacaram,"},
{v:76,t:"e os da cidade, com medo, abriram as portas; e Jônatas tornou-se senhor de Jope."},
{v:77,t:"Quando Apolônio soube disso, reuniu três mil cavaleiros e um exército numeroso e marchou para Azoto, como quem apenas passa, mas logo avançou para a planície, porque tinha muita cavalaria e confiava nela.",np:1},
{v:78,t:"Jônatas o perseguiu até Azoto, e os exércitos travaram combate."},
{v:79,t:"Apolônio tinha deixado mil cavaleiros escondidos atrás deles."},
{v:80,t:"Jônatas percebeu que havia uma emboscada atrás dele. Os cavaleiros cercaram o seu exército e atiraram dardos contra o povo, desde a manhã até a tarde."},
{v:81,t:"Mas o povo manteve a posição, como Jônatas ordenara, e os cavalos dos inimigos se cansaram."},
{v:82,t:"Então Simão lançou as suas tropas e atacou a falange, pois a cavalaria já estava esgotada; foram esmagados por ele e fugiram."},
{v:83,t:"A cavalaria dispersou-se pela planície; fugiram para Azoto e entraram em Bet-Dagon, o templo do seu ídolo, para se salvar."},
{v:84,t:"Jônatas incendiou Azoto e as cidades ao redor, tomou os seus despojos e queimou o templo de Dagon com todos os que nele se tinham refugiado."},
{v:85,t:"Os que caíram pela espada, junto com os que morreram queimados, foram cerca de oito mil homens."},
{v:86,t:"Jônatas partiu dali e acampou diante de Ascalon; os habitantes da cidade saíram ao seu encontro com grandes honras."},
{v:87,t:"Depois Jônatas voltou para Jerusalém com os seus homens, carregados de despojos."},
{v:88,t:"Quando o rei Alexandre soube desses acontecimentos, honrou Jônatas ainda mais:"},
{v:89,t:"enviou-lhe uma fivela de ouro, como se costuma dar aos parentes dos reis, e deu-lhe Acaron com todo o seu território como propriedade.",n:"Parente do rei era o título mais alto da corte selêucida, acima de amigo do rei."}
];

window.TEXTOS_SEED["1macabeus"][11] = [
{s:"Ptolomeu contra Alexandre"},
{v:1,t:"O rei do Egito reuniu um exército numeroso como a areia da praia do mar e muitos navios, e procurou apoderar-se à traição do reino de Alexandre e anexá-lo ao seu."},
{v:2,t:"Foi à Síria com palavras de paz, e os habitantes das cidades lhe abriam as portas e saíam ao seu encontro, porque o rei Alexandre mandara recebê-lo, por ser seu sogro."},
{v:3,t:"Mas, ao entrar nas cidades, Ptolomeu deixava as suas tropas como guarnição em cada uma delas."},
{v:4,t:"Quando chegou perto de Azoto, mostraram-lhe o templo de Dagon incendiado, Azoto e os seus arredores em ruínas, os cadáveres atirados por terra e os restos dos que Jônatas queimara na batalha; tinham feito montes com eles ao longo do seu caminho."},
{v:5,t:"Contaram ao rei o que Jônatas fizera, para que ele o censurasse; mas o rei ficou calado."},
{v:6,t:"Jônatas foi com pompa ao encontro do rei em Jope; saudaram-se e passaram ali a noite."},
{v:7,t:"Jônatas acompanhou o rei até o rio chamado Eleutero e voltou para Jerusalém."},
{v:8,t:"O rei Ptolomeu tornou-se senhor das cidades do litoral até Selêucia Marítima e tramava planos perversos contra Alexandre.",np:1},
{v:9,t:"Enviou embaixadores ao rei Demétrio, dizendo: Vem, façamos um pacto entre nós; eu te darei a minha filha, que foi dada a Alexandre, e reinarás no reino de teu pai;"},
{v:10,t:"pois me arrependo de lhe ter dado a minha filha: ele procurou matar-me."},
{v:11,t:"Assim o difamava, porque cobiçava o seu reino."},
{v:12,t:"Tirou-lhe a filha e a deu a Demétrio; afastou-se de Alexandre, e a inimizade entre eles tornou-se manifesta."},
{v:13,t:"Ptolomeu entrou em Antioquia e pôs na cabeça dois diademas, o do Egito e o da Ásia."},
{v:14,t:"Naquele tempo, o rei Alexandre estava na Cilícia, porque a gente daquela região se tinha revoltado."},
{v:15,t:"Quando Alexandre soube disso, veio atacá-lo; Ptolomeu saiu com o exército, enfrentou-o com forças poderosas e o pôs em fuga."},
{v:16,t:"Alexandre fugiu para a Arábia, para buscar proteção ali; e o rei Ptolomeu triunfou."},
{v:17,t:"Zabdiel, o árabe, cortou a cabeça de Alexandre e a enviou a Ptolomeu."},
{v:18,t:"Mas, três dias depois, o rei Ptolomeu morreu, e os soldados que ele deixara nas fortalezas foram mortos pelos habitantes das fortalezas."},
{v:19,t:"E Demétrio começou a reinar no ano cento e sessenta e sete.",n:"Em 145 a.C."},
{s:"Jônatas e Demétrio II"},
{v:20,t:"Naqueles dias, Jônatas reuniu os homens da Judeia para atacar a Cidadela de Jerusalém, e construiu contra ela muitas máquinas de guerra."},
{v:21,t:"Alguns homens sem lei, que odiavam a própria nação, foram contar ao rei que Jônatas sitiava a Cidadela."},
{v:22,t:"O rei enfureceu-se ao ouvir isso; partiu imediatamente, foi a Ptolemaida e escreveu a Jônatas que levantasse o cerco e viesse o mais depressa possível encontrar-se com ele em Ptolemaida."},
{v:23,t:"Quando Jônatas recebeu a carta, mandou continuar o cerco; escolheu alguns anciãos de Israel e alguns sacerdotes e expôs-se ao perigo:"},
{v:24,t:"levando prata, ouro, vestes e muitos outros presentes, foi ter com o rei em Ptolemaida e caiu nas suas graças."},
{v:25,t:"Alguns homens sem lei da sua nação apresentaram queixas contra ele,"},
{v:26,t:"mas o rei o tratou como os seus antecessores o tinham tratado e o honrou diante de todos os seus amigos;"},
{v:27,t:"confirmou-o no sumo sacerdócio e em todas as outras honras que antes tinha, e o fez contar entre os seus primeiros amigos."},
{v:28,t:"Jônatas pediu ao rei que isentasse de impostos a Judeia, os três distritos e a Samaria, prometendo-lhe trezentos talentos.",np:1},
{v:29,t:"O rei consentiu e escreveu a Jônatas, a respeito de tudo isso, cartas deste teor:"},
{v:30,t:"O rei Demétrio saúda o seu irmão Jônatas e a nação dos judeus."},
{v:31,t:"Enviamos também a vós, para vosso conhecimento, a cópia da carta que escrevemos a vosso respeito a Lástenes, nosso parente:"},
{v:32,t:"O rei Demétrio saúda Lástenes, seu pai.",np:1,n:"Pai e parente: títulos honoríficos da corte. Lástenes era o comandante dos mercenários cretenses de Demétrio."},
{v:33,t:"Decidimos beneficiar a nação dos judeus, nossos amigos, que cumprem fielmente os seus deveres para conosco, por causa da boa vontade que nos mostram."},
{v:34,t:"Confirmamos-lhes o território da Judeia e os três distritos de Aferema, Lida e Ramataim, que foram anexados à Judeia, tirados da Samaria, com todas as suas dependências, em favor de todos os que oferecem sacrifícios em Jerusalém, em lugar dos tributos reais que o rei recebia deles todos os anos dos produtos da terra e das árvores."},
{v:35,t:"Quanto aos outros direitos que nos cabem, de agora em diante — os dízimos e as taxas que nos pertencem, as salinas e as coroas que nos são devidas —, tudo lhes concedemos."},
{v:36,t:"Nada disso será revogado, de agora em diante e para sempre."},
{v:37,t:"Cuidai, pois, de fazer uma cópia deste decreto, que seja entregue a Jônatas e afixada no monte santo, em lugar bem visível."},
{s:"Trifão e o jovem Antíoco"},
{v:38,t:"Vendo que a terra estava tranquila diante dele e que ninguém lhe resistia, o rei Demétrio dispensou todo o seu exército, mandando cada um para a sua casa, exceto as tropas estrangeiras que recrutara nas ilhas das nações. Por isso, todas as tropas que tinham servido aos seus pais se tornaram suas inimigas."},
{v:39,t:"Trifão, que antes tinha sido partidário de Alexandre, viu que todas as tropas murmuravam contra Demétrio; foi ter com Imalcue, o árabe, que criava Antíoco, o filho pequeno de Alexandre,"},
{v:40,t:"e insistiu com ele para que lhe entregasse o menino, a fim de fazê-lo reinar em lugar do pai. Contou-lhe tudo o que Demétrio fizera e o ódio que as suas tropas lhe tinham; e ficou ali muitos dias."},
{s:"Os judeus salvam Demétrio em Antioquia"},
{v:41,t:"Jônatas mandou pedir ao rei Demétrio que retirasse de Jerusalém os homens da Cidadela e as guarnições das fortalezas, porque combatiam contra Israel."},
{v:42,t:"Demétrio respondeu a Jônatas: Não só farei isso por ti e pela tua nação, mas cobrirei de glória a ti e à tua nação, quando tiver ocasião."},
{v:43,t:"Agora, porém, farás bem em me enviar homens que combatam comigo, porque todas as minhas tropas desertaram."},
{v:44,t:"Jônatas enviou-lhe a Antioquia três mil homens valentes; eles chegaram junto do rei, que se alegrou com a sua vinda."},
{v:45,t:"Os habitantes da cidade, uns cento e vinte mil homens, reuniram-se no centro da cidade, querendo matar o rei."},
{v:46,t:"O rei refugiou-se no palácio, e os habitantes ocuparam as ruas da cidade e começaram o ataque."},
{v:47,t:"O rei chamou os judeus em seu socorro; todos juntos se reuniram em torno dele, espalharam-se pela cidade e naquele dia mataram uns cem mil homens."},
{v:48,t:"Incendiaram a cidade, tomaram naquele dia muitos despojos e salvaram o rei."},
{v:49,t:"Os habitantes viram que os judeus eram senhores da cidade e faziam o que queriam; perderam o ânimo e clamaram ao rei, suplicando:"},
{v:50,t:"Dá-nos a mão direita, e que os judeus parem de atacar a nós e à cidade."},
{v:51,t:"Largaram as armas e fizeram a paz. Os judeus foram honrados diante do rei e de todos os do seu reino, ganharam fama no reino e voltaram para Jerusalém carregados de despojos."},
{v:52,t:"O rei Demétrio sentou-se no trono do seu reino, e a terra ficou tranquila diante dele."},
{v:53,t:"Mas faltou a tudo o que tinha prometido, afastou-se de Jônatas, não lhe retribuiu os favores que dele recebera e o maltratou muito."},
{s:"Jônatas, aliado de Antíoco VI"},
{v:54,t:"Depois disso, Trifão voltou, trazendo consigo o menino Antíoco, que foi proclamado rei e cingiu o diadema.",n:"Antíoco VI, em 145 a.C."},
{v:55,t:"Juntaram-se a ele todas as tropas que Demétrio dispensara, e combateram contra Demétrio, que foi derrotado e fugiu."},
{v:56,t:"Trifão apoderou-se dos elefantes e ocupou Antioquia."},
{v:57,t:"O jovem Antíoco escreveu a Jônatas: Confirmo-te no sumo sacerdócio, ponho-te à frente dos quatro distritos e te declaro um dos amigos do rei."},
{v:58,t:"Enviou-lhe também vasos de ouro e um serviço de mesa, e concedeu-lhe o direito de beber em taças de ouro, de vestir-se de púrpura e de usar a fivela de ouro.",np:1},
{v:59,t:"E nomeou o seu irmão Simão governador militar desde a Escada de Tiro até a fronteira do Egito.",n:"A Escada de Tiro era um promontório íngreme ao sul de Tiro."},
{v:60,t:"Jônatas saiu e percorreu a Transeufratênia e as suas cidades, e todo o exército da Síria se juntou a ele como aliado. Foi a Ascalon, e os habitantes da cidade o receberam com honras."},
{v:61,t:"Dali foi a Gaza, mas os habitantes lhe fecharam as portas; ele a sitiou, incendiou os seus arredores e os saqueou."},
{v:62,t:"Os de Gaza pediram paz a Jônatas; ele lhes deu a mão direita, tomou como reféns os filhos dos seus chefes e os mandou para Jerusalém. Depois percorreu a região até Damasco."},
{s:"A batalha de Hasor"},
{v:63,t:"Jônatas soube que os generais de Demétrio tinham chegado a Cades, na Galileia, com um grande exército, querendo afastá-lo do seu cargo;"},
{v:64,t:"e saiu ao encontro deles, deixando na região o seu irmão Simão."},
{v:65,t:"Simão acampou diante de Bet-Sur, atacou-a durante muitos dias e a manteve cercada."},
{v:66,t:"Os sitiados pediram-lhe a mão direita, e ele a deu; expulsou-os dali, ocupou a cidade e pôs nela uma guarnição."},
{v:67,t:"Jônatas e o seu exército acamparam junto às águas de Genesaré e, de madrugada, avançaram para a planície de Hasor.",np:1},
{v:68,t:"E eis que o exército dos estrangeiros vinha ao seu encontro na planície; tinham deixado uma emboscada contra ele nas montanhas, enquanto eles mesmos o enfrentavam pela frente."},
{v:69,t:"Os da emboscada saíram dos seus esconderijos e atacaram."},
{v:70,t:"Todos os homens de Jônatas fugiram; não ficou nenhum, a não ser Matatias, filho de Absalão, e Judas, filho de Calfi, comandantes do exército."},
{v:71,t:"Jônatas rasgou as vestes, pôs terra sobre a cabeça e rezou."},
{v:72,t:"Depois voltou a combater contra eles e os desbaratou, e eles fugiram."},
{v:73,t:"Vendo isso, os seus homens que fugiam voltaram para junto dele e perseguiram com ele os inimigos até Cades, até o acampamento deles, e acamparam ali."},
{v:74,t:"Caíram naquele dia uns três mil estrangeiros. E Jônatas voltou para Jerusalém."}
];

window.TEXTOS_SEED["1macabeus"][12] = [
{s:"A amizade com Roma e com Esparta"},
{v:1,t:"Jônatas viu que o momento lhe era favorável; escolheu alguns homens e os enviou a Roma para confirmar e renovar a amizade com os romanos."},
{v:2,t:"Mandou também cartas no mesmo sentido aos espartanos e a outros lugares."},
{v:3,t:"Foram a Roma, entraram no senado e disseram: Jônatas, o sumo sacerdote, e a nação dos judeus nos enviaram para renovar convosco a amizade e a aliança, como antes."},
{v:4,t:"Os romanos lhes deram cartas para as autoridades de cada lugar, para que os fizessem chegar em paz à terra de Judá."},
{v:5,t:"Esta é a cópia da carta que Jônatas escreveu aos espartanos:"},
{v:6,t:"Jônatas, sumo sacerdote, o conselho dos anciãos da nação, os sacerdotes e o resto do povo judeu saúdam os espartanos, seus irmãos."},
{v:7,t:"Já há tempo, Ário, que reinava entre vós, enviou ao sumo sacerdote Onias uma carta dizendo que sois nossos irmãos, como mostra a cópia que vai abaixo.",n:"Ário I foi rei de Esparta de 309 a 265 a.C.; Onias I era sumo sacerdote por volta de 300 a.C. Não se sabe de onde vem a tradição de parentesco entre espartanos e judeus."},
{v:8,t:"Onias recebeu com honra o enviado e aceitou a carta, que falava de aliança e de amizade."},
{v:9,t:"Quanto a nós, embora não precisemos de nada disso, pois temos como consolo os livros santos que estão em nossas mãos,"},
{v:10,t:"procuramos mandar-vos mensageiros para renovar a fraternidade e a amizade convosco, para não nos tornarmos estranhos para vós, pois já passou muito tempo desde que nos escrevestes."},
{v:11,t:"Nós, em todo tempo e sem cessar, nas festas e nos outros dias estabelecidos, nos lembramos de vós nos sacrifícios que oferecemos e nas orações, como é justo e conveniente lembrar-se dos irmãos."},
{v:12,t:"Alegramo-nos com a vossa glória."},
{v:13,t:"Quanto a nós, muitas tribulações e muitas guerras nos cercaram, e os reis vizinhos nos atacaram."},
{v:14,t:"Não quisemos importunar-vos, nem os nossos outros aliados e amigos, nessas guerras,"},
{v:15,t:"porque temos o auxílio que vem do Céu, que nos socorre; fomos livrados dos nossos inimigos, e os nossos inimigos foram humilhados."},
{v:16,t:"Escolhemos, pois, Numênio, filho de Antíoco, e Antípatro, filho de Jasão, e os enviamos aos romanos para renovar a antiga amizade e aliança com eles."},
{v:17,t:"Ordenamos-lhes que fossem também a vós, para vos saudar e entregar esta nossa carta sobre a renovação da nossa fraternidade."},
{v:18,t:"Fareis bem em nos responder a respeito disso."},
{v:19,t:"Esta é a cópia da carta que tinham enviado a Onias:",np:1},
{v:20,t:"Ário, rei dos espartanos, saúda o sumo sacerdote Onias."},
{v:21,t:"Encontrou-se num escrito, a respeito dos espartanos e dos judeus, que são irmãos e que são da raça de Abraão."},
{v:22,t:"Agora que o sabemos, fareis bem em nos escrever sobre a vossa prosperidade.",np:1},
{v:23,t:"Nós, por nossa vez, vos escrevemos: o vosso gado e os vossos bens são nossos, e os nossos são vossos. Ordenamos, pois, que vos transmitam esta mensagem."},
{s:"Novas campanhas de Jônatas e de Simão"},
{v:24,t:"Jônatas soube que os generais de Demétrio tinham voltado para atacá-lo com um exército maior do que antes."},
{v:25,t:"Saiu de Jerusalém e foi ao encontro deles na região de Emat, sem lhes dar tempo de entrar no seu território."},
{v:26,t:"Mandou espiões ao acampamento deles; e estes voltaram dizendo que os inimigos se preparavam para atacá-los de noite."},
{v:27,t:"Ao pôr do sol, Jônatas ordenou aos seus que vigiassem e ficassem em armas, prontos para o combate, a noite inteira; e pôs sentinelas ao redor do acampamento."},
{v:28,t:"Os adversários souberam que Jônatas e os seus estavam prontos para o combate; tiveram medo, ficaram apavorados e acenderam fogueiras no seu acampamento.",n:"As fogueiras acesas deviam fazer crer que continuavam no acampamento, enquanto fugiam."},
{v:29,t:"Jônatas e os seus só perceberam isso de manhã, porque viam as fogueiras acesas."},
{v:30,t:"Jônatas os perseguiu, mas não os alcançou, porque já tinham atravessado o rio Eleutero."},
{v:31,t:"Então Jônatas voltou-se contra os árabes chamados zabadeus, derrotou-os e tomou os seus despojos."},
{v:32,t:"Depois levantou o acampamento, foi a Damasco e percorreu toda aquela região."},
{v:33,t:"Simão também saiu e avançou até Ascalon e as fortalezas vizinhas; desviou-se para Jope e a ocupou,"},
{v:34,t:"porque soubera que os habitantes queriam entregar a fortaleza aos partidários de Demétrio; e pôs ali uma guarnição para guardá-la."},
{s:"As obras em Jerusalém"},
{v:35,t:"Quando Jônatas voltou, convocou os anciãos do povo e decidiu com eles construir fortalezas na Judeia,"},
{v:36,t:"elevar as muralhas de Jerusalém e levantar um muro alto entre a Cidadela e a cidade, para separá-la da cidade e isolá-la, de modo que os da Cidadela não pudessem comprar nem vender."},
{v:37,t:"Reuniram-se para reconstruir a cidade; e, como parte da muralha junto à torrente, do lado do oriente, tinha desabado, restauraram-na; é o bairro chamado Cafenata."},
{v:38,t:"Simão reconstruiu Adida, na Sefelá, fortificou-a e pôs-lhe portas e ferrolhos."},
{s:"Trifão prende Jônatas"},
{v:39,t:"Trifão procurava reinar sobre a Ásia, cingir o diadema e pôr as mãos no rei Antíoco."},
{v:40,t:"Mas temia que Jônatas não o deixasse fazer isso e que lhe fizesse guerra; por isso procurava prendê-lo e matá-lo. Partiu e foi a Bet-San."},
{v:41,t:"Jônatas saiu ao seu encontro com quarenta mil homens escolhidos para a batalha e chegou a Bet-San."},
{v:42,t:"Quando Trifão viu que ele tinha vindo com um grande exército, teve medo de pôr as mãos nele;"},
{v:43,t:"recebeu-o com honra, apresentou-o a todos os seus amigos, deu-lhe presentes e ordenou às suas tropas que lhe obedecessem como a ele mesmo."},
{v:44,t:"E disse a Jônatas: Por que cansaste todo este povo, se não há guerra entre nós?"},
{v:45,t:"Manda-os de volta para as suas casas; escolhe só alguns homens que fiquem contigo e vem comigo a Ptolemaida. Eu te entregarei a cidade, as outras fortalezas, as outras tropas e todos os funcionários; depois voltarei para casa, pois foi para isso que vim.",np:1},
{v:46,t:"Jônatas confiou nele e fez como ele dizia: despediu as tropas, que voltaram para a terra de Judá."},
{v:47,t:"Ficou só com três mil homens, dos quais deixou dois mil na Galileia; mil foram com ele."},
{v:48,t:"Mas, assim que Jônatas entrou em Ptolemaida, os habitantes fecharam as portas e o prenderam; e mataram à espada todos os que tinham entrado com ele.",np:1},
{v:49,t:"Trifão enviou tropas e cavalaria à Galileia e à grande planície, para exterminar todos os partidários de Jônatas.",np:1},
{v:50,t:"Estes, pensando que Jônatas tinha sido preso e que tinha perecido com os seus companheiros, encorajaram-se uns aos outros e marcharam em formação cerrada, prontos para o combate.",n:"Na realidade, Jônatas ainda estava vivo (13,12–23)."},
{v:51,t:"Os perseguidores, vendo que eles estavam dispostos a lutar pela vida, voltaram atrás."},
{v:52,t:"Todos chegaram em paz à terra de Judá; choraram Jônatas e os seus companheiros e ficaram com muito medo. E todo o Israel fez um grande luto."},
{v:53,t:"Todas as nações ao redor procuraram então esmagá-los, pois diziam:"},
{v:54,t:"Não têm chefe nem quem os ajude; ataquemo-los agora e apaguemos a sua memória dentre os homens."}
];

window.TEXTOS_SEED["1macabeus"][13] = [
{s:"Simão, chefe do povo"},
{v:1,t:"Simão soube que Trifão tinha reunido um grande exército para invadir a terra de Judá e devastá-la."},
{v:2,t:"Vendo que o povo tremia de medo, subiu a Jerusalém, reuniu o povo"},
{v:3,t:"e o encorajou, dizendo: Vós mesmos sabeis quanto eu, os meus irmãos e a casa de meu pai fizemos pelas leis e pelo santuário, e que guerras e aflições conhecemos."},
{v:4,t:"Foi por isso que todos os meus irmãos morreram por Israel, e só eu fiquei."},
{v:5,t:"E agora, longe de mim poupar a minha vida em qualquer momento de aflição, pois não sou melhor do que os meus irmãos.",np:1},
{v:6,t:"Pelo contrário, vingarei a minha nação, o santuário, as vossas mulheres e os vossos filhos, porque todas as nações se reuniram por ódio para nos esmagar."},
{v:7,t:"Ao ouvir essas palavras, o povo recobrou o ânimo"},
{v:8,t:"e respondeu em alta voz: Tu és o nosso chefe, em lugar de Judas e de Jônatas, teu irmão."},
{v:9,t:"Conduze a nossa guerra, e faremos tudo o que nos disseres."},
{v:10,t:"Simão reuniu todos os homens de guerra, apressou-se a terminar as muralhas de Jerusalém e fortificou-a ao redor."},
{v:11,t:"Enviou a Jope Jônatas, filho de Absalão, com um exército considerável; este expulsou os habitantes e ficou ali."},
{s:"Trifão mata Jônatas"},
{v:12,t:"Trifão partiu de Ptolemaida com um grande exército para invadir a terra de Judá, levando Jônatas preso consigo."},
{v:13,t:"Simão acampou em Adida, diante da planície."},
{v:14,t:"Trifão soube que Simão tinha tomado o lugar do seu irmão Jônatas e que ia dar-lhe combate; enviou-lhe então mensageiros"},
{v:15,t:"para dizer-lhe: É por causa do dinheiro que o teu irmão Jônatas devia ao tesouro real, pelos cargos que ocupava, que o retemos."},
{v:16,t:"Envia agora cem talentos de prata e dois dos seus filhos como reféns, para que, uma vez solto, não se revolte contra nós; e o soltaremos."},
{v:17,t:"Simão percebeu que lhe falavam com astúcia; mesmo assim mandou buscar o dinheiro e os meninos, para não atrair sobre si um grande ódio do povo,"},
{v:18,t:"que poderia dizer: Porque ele não lhe mandou o dinheiro e os meninos, Jônatas morreu."},
{v:19,t:"Enviou, pois, os meninos e os cem talentos; mas Trifão mentiu e não soltou Jônatas."},
{v:20,t:"Depois disso, Trifão avançou para invadir e devastar a região, dando uma volta pelo caminho de Adora; mas Simão e o seu exército o acompanhavam de perto por onde quer que fosse."},
{v:21,t:"Os da Cidadela enviavam mensageiros a Trifão, insistindo para que viesse até eles pelo deserto e lhes mandasse víveres."},
{v:22,t:"Trifão preparou toda a sua cavalaria para ir; mas naquela noite caiu muita neve, e ele não pôde ir por causa da neve. Levantou o acampamento e foi para a região de Galaad."},
{v:23,t:"Quando chegou perto de Bascama, matou Jônatas, que foi sepultado ali;",np:1,n:"Em 143 a.C."},
{v:24,t:"depois Trifão voltou para a sua terra."},
{s:"O túmulo dos Macabeus em Modin"},
{v:25,t:"Simão mandou recolher os ossos do seu irmão Jônatas e o sepultou em Modin, a cidade dos seus pais."},
{v:26,t:"Todo o Israel fez por ele um grande luto e o chorou durante muitos dias."},
{v:27,t:"Sobre o túmulo do seu pai e dos seus irmãos, Simão construiu um monumento alto, que se via de longe, revestido de pedra polida por trás e pela frente."},
{v:28,t:"Levantou sete pirâmides, uma diante da outra, para o pai, a mãe e os quatro irmãos.",n:"A sétima pirâmide seria para o próprio Simão."},
{v:29,t:"Rodeou-as de grandes colunas, e sobre as colunas pôs armaduras completas, para memória eterna, e, junto às armaduras, navios esculpidos, que todos os que navegavam pelo mar pudessem ver."},
{v:30,t:"Esse é o túmulo que ele construiu em Modin e que existe até hoje."},
{s:"Simão e Demétrio II"},
{v:31,t:"Trifão agia com traição para com o jovem rei Antíoco; matou-o"},
{v:32,t:"e reinou em seu lugar; cingiu o diadema da Ásia e causou grandes males ao país."},
{v:33,t:"Simão reconstruiu as fortalezas da Judeia, cercou-as de torres altas, de grandes muralhas, de portas e ferrolhos, e armazenou víveres nas fortalezas."},
{v:34,t:"Simão escolheu alguns homens e os enviou ao rei Demétrio, pedindo isenção de impostos para a região, porque tudo o que Trifão fazia era roubo."},
{v:35,t:"O rei Demétrio respondeu-lhe favoravelmente, escrevendo-lhe esta carta:",np:1},
{v:36,t:"O rei Demétrio saúda Simão, sumo sacerdote e amigo dos reis, os anciãos e a nação dos judeus.",np:1},
{v:37,t:"Recebemos a coroa de ouro e a palma que nos enviastes; estamos dispostos a fazer convosco uma paz completa e a escrever aos funcionários que vos concedam isenções."},
{v:38,t:"Tudo o que estabelecemos convosco continua válido, e as fortalezas que construístes fiquem em vosso poder."},
{v:39,t:"Perdoamos as faltas e as ofensas cometidas até hoje e a coroa que devíeis; e, se alguma outra taxa se cobrava em Jerusalém, não seja mais cobrada."},
{v:40,t:"Se alguns de vós forem aptos para ser alistados na nossa guarda, que sejam alistados; e haja paz entre nós."},
{v:41,t:"No ano cento e setenta, o jugo das nações foi tirado de Israel.",np:1,n:"Em 142 a.C."},
{v:42,t:"E o povo de Israel começou a escrever nos documentos e nos contratos: No primeiro ano de Simão, grande sumo sacerdote, general e chefe dos judeus."},
{s:"A tomada de Gazer e da Cidadela"},
{v:43,t:"Naqueles dias, Simão acampou diante de Gazer, cercou-a com as suas tropas, construiu uma torre de assalto, aproximou-a da cidade, derrubou uma das torres e a tomou."},
{v:44,t:"Os que estavam na torre de assalto saltaram para dentro da cidade, e houve grande agitação na cidade."},
{v:45,t:"Os habitantes subiram à muralha com as mulheres e os filhos, com as vestes rasgadas, e gritaram em alta voz, pedindo a Simão que lhes desse a mão direita."},
{v:46,t:"Diziam: Não nos trates segundo as nossas maldades, mas segundo a tua misericórdia."},
{v:47,t:"Simão fez um acordo com eles e não os combateu; mas expulsou-os da cidade, purificou as casas onde havia ídolos e então entrou nela cantando hinos e bendizendo a Deus."},
{v:48,t:"Tirou dela toda impureza, estabeleceu nela homens que observassem a Lei, fortificou-a e construiu ali uma residência para si."},
{v:49,t:"Os da Cidadela de Jerusalém estavam impedidos de sair e entrar na região para comprar e vender; passaram muita fome, e bom número deles morreu de fome.",np:1},
{v:50,t:"Clamaram a Simão, pedindo-lhe a mão direita, e ele a deu; expulsou-os dali e purificou a Cidadela das contaminações."},
{v:51,t:"Entraram nela no dia vinte e três do segundo mês do ano cento e setenta e um, com cânticos de louvor e ramos de palmeira, com cítaras, címbalos e harpas, com hinos e canções, porque um grande inimigo tinha sido eliminado de Israel.",n:"Junho de 141 a.C."},
{v:52,t:"Simão determinou que esse dia fosse celebrado todos os anos com alegria."},
{v:53,t:"Fortificou também o monte do templo, junto à Cidadela, e morou ali com os seus."},
{v:54,t:"Vendo que o seu filho João já era um homem feito, Simão o nomeou comandante de todas as tropas; e João foi morar em Gazer."}
];
